// ══════════ src/mask.js ══════════
// GENERATED by scripts/generate-mask.js — do not edit by hand.
// Land bitmask, 512×256 equirectangular cells (row-major from
// lat +90 down, lon −180 → +180), 1 bit per cell, base64-packed.
// Data: Natural Earth 110m land (public domain, naturalearthdata.com).

export const MASK_W = 512;
export const MASK_H = 256;

const BITS = /* base64 */ Uint8Array.from(atob(""), (c) => c.charCodeAt(0));

// Is there land at this latitude/longitude? The single primitive the whole
// renderer derives from.
export function isLand(lat, lon) {
  if (lat > 90 || lat < -90) return false;
  const col = Math.min(MASK_W - 1, Math.max(0, Math.floor(((lon + 180) / 360) * MASK_W)));
  const row = Math.min(MASK_H - 1, Math.max(0, Math.floor(((90 - lat) / 180) * MASK_H)));
  const idx = row * MASK_W + col;
  return (BITS[idx >> 3] & (1 << (idx & 7))) !== 0;
}

// ══════════ src/projection.js ══════════
// Equirectangular projection — the deliberate choice for a SYMBOLIC map:
// linear lat/lon ↔ x/y, matching both the packed land mask and everyone's
// mental image of "the world map". Not area-accurate (Mercator-style debates
// don't apply — nothing here encodes quantity by area).
//
// All renderer geometry flows through these two functions, which is what
// makes the future globe mode a renderer swap instead of an API change:
// callers speak lat/lon, only the projection changes.

// Map a lat/lon to fractional grid coordinates in a cols×rows grid covering
// latRange (north→south) across the full −180…180 longitude span.
export function project(lat, lon, { cols, rows, latRange }) {
  const [latMin, latMax] = latRange;
  return {
    x: ((lon + 180) / 360) * cols,
    y: ((latMax - lat) / (latMax - latMin)) * rows
  };
}

// The center lat/lon of a grid cell — where the mask is sampled and where a
// dot is drawn.
export function cellCenter(col, row, { cols, rows, latRange }) {
  const [latMin, latMax] = latRange;
  return {
    lat: latMax - ((row + 0.5) / rows) * (latMax - latMin),
    lon: -180 + ((col + 0.5) / cols) * 360
  };
}

// Normalized projection: lat/lon → {x, y} in 0…1 across the rendered box.
//
// This is the one a HOST needs. `project` above answers in grid units, which
// requires `rows` — and rows is derived internally from cols and latRange, so
// asking a consuming app for it forces that app to re-derive mappo's own
// arithmetic (and to keep re-deriving it correctly forever). Normalized
// coordinates need neither: the viewBox is linear in the grid, so 0…1 maps
// straight onto CSS percentages, canvas pixels, or a server-rendered
// `style="left:%"` in a template in any language.
export function projectNormalized(lat, lon, { latRange } = {}) {
  const [ latMin, latMax ] = latRange ?? [ -58, 84 ];
  return {
    x: (lon + 180) / 360,
    y: (latMax - lat) / (latMax - latMin)
  };
}

// The lat/lon of a grid CORNER — where cell boundaries live, and therefore
// where coastline geometry lives. cellCenter answers for the middle of a cell;
// contours are traced along its edges, so they need this. Same linear mapping,
// no +0.5 offset.
export function cellCorner(col, row, { cols, rows, latRange }) {
  const [ latMin, latMax ] = latRange;
  return {
    lat: latMax - (row / rows) * (latMax - latMin),
    lon: -180 + (col / cols) * 360
  };
}

// ══════════ src/graticule.js ══════════
// The graticule: meridians, parallels, and the equator, as lat/lon polylines.
//
// Renderer-agnostic on purpose — the same discipline as highlight.js. This
// module knows nothing about SVG, canvas, spheres or grids; it emits lines in
// world coordinates and each renderer projects them its own way. That is what
// lets the flat map and the globe share one definition of "the grid on the
// world" instead of drifting apart.
//
// Two rules here are not arbitrary, they are what makes a graticule readable:
//
//   1. The EQUATOR IS ITS OWN LINE, returned separately, so a renderer can
//      give it its own colour and weight. It is the line a reader orients
//      against; drowning it in eleven identical parallels wastes it.
//   2. A parallel that lands within `skipDeg` of the equator is DROPPED
//      rather than drawn. Evenly spacing parallels across 180° will, for many
//      counts, put one right on 0° — which double-draws the equator at double
//      opacity and makes it look like a rendering bug.

// Sampling step in degrees along each line. 3° gives a circle of 120
// segments, which stays smooth at any globe size a browser will draw and
// still costs nothing to project.
const STEP = 3;

function ring(fn) {
  const pts = [];
  for (let d = 0; d <= 360; d += STEP) pts.push(fn(d));
  return pts;
}

// A full meridian: pole to pole and back is unnecessary — a half circle from
// -90 to 90 is the whole line, and the renderer decides how much of it is
// visible.
function meridian(lon) {
  const pts = [];
  for (let lat = -90; lat <= 90; lat += STEP) pts.push([ lat, lon ]);
  return pts;
}

function parallel(lat) {
  return ring((d) => [ lat, -180 + d ]);
}

// meridians: how many evenly spaced longitudes (0 disables).
// parallels: how many evenly spaced latitudes BETWEEN the poles, equator
//            excluded (it is always returned separately).
// skipDeg:   parallels closer than this to the equator are dropped.
export function buildGraticule({ meridians = 12, parallels = 11, skipDeg = 5 } = {}) {
  const mers = [];
  for (let i = 0; i < meridians; i++) mers.push(meridian(-180 + (360 / meridians) * i));

  const pars = [];
  for (let i = 0; i < parallels; i++) {
    const lat = -90 + (180 / (parallels + 1)) * (i + 1);
    if (Math.abs(lat) < skipDeg) continue;
    pars.push(parallel(lat));
  }

  return { meridians: mers, parallels: pars, equator: parallel(0) };
}

// ══════════ src/shapes.js ══════════
// GENERATED by scripts/generate-shapes.js — do not edit.
//
// Vector coastlines and country borders from Natural Earth 110m (public
// domain), quantized to 1/32° and delta+varint encoded. The same source
// the bitmask is rasterized from, kept as outlines instead: this is what
// land-source="vector" draws.
//
// Decoded lazily and memoized — a map that never asks for vector land pays
// only the bytes, never the parse.

const SHAPE_SCALE = 32;
const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const INDEX = (() => {
  const m = new Map();
  for (let i = 0; i < ALPHABET.length; i++) m.set(ALPHABET[i], i);
  return m;
})();

function decodeRings(encoded) {
  const rings = [];
  for (const chunk of encoded.split("|")) {
    const ring = [];
    let i = 0, px = 0, py = 0;
    while (i < chunk.length) {
      const read = () => {
        let shift = 0, result = 0, byte;
        do {
          byte = INDEX.get(chunk[i++]);
          result += (byte & 31) * Math.pow(32, shift / 5);
          shift += 5;
        } while (byte >= 32);
        return (result % 2) ? ~((result - 1) / 2) : result / 2;   // un-zigzag
      };
      px += read();
      py += read();
      ring.push([ py / SHAPE_SCALE - 90, px / SHAPE_SCALE - 180 ]);   // [lat, lon]
    }
    if (ring.length > 2) rings.push(ring);
  }
  return rings;
}

