let _land = null, _countries = null;

// Coastlines: the outline of every landmass. Rings of [lat, lon].
export function landShapes() {
  return (_land ??= decodeRings(RAW_LAND));
}

// Country borders, as closed rings of [lat, lon].
export function countryShapes() {
  return (_countries ??= decodeRings(RAW_COUNTRIES));
}

// ══════════ src/land.js ══════════
// Land as SHAPE — the single source of truth behind every non-dot land style,
// on both renderers.
//
// One sampling pass produces two things:
//
//   cells — the land cells themselves, for anything that fills by cell (the
//           globe fills projected quads, because a filled outline that crosses
//           the limb cannot be closed correctly on a sphere).
//   loops — the CLOSED boundary contours of the landmass, in grid-corner
//           coordinates, for anything that draws the coastline (the flat map
//           fills and strokes the very same path; the globe strokes it).
//
// Why contours and not "a rectangle per cell": a rectangle grid strokes every
// internal cell edge, which draws a wireframe, not a coastline. Tracing the
// boundary means the outline is exactly where land meets sea and nowhere else —
// and because the loops are closed and consistently wound, the SAME path data
// fills correctly, holes included. That is what lets `solid`, `outline` and
// `solid outline` be three renderings of one geometry rather than three
// implementations that can disagree.
//
// Winding: outer rings run clockwise in screen space (y down), holes run
// counter-clockwise, which is what `fill-rule: nonzero` wants — inland seas
// stay empty without anyone declaring them.


const cache = new Map();

// wrapX: treat column -1 and column `cols` as the far side of the map. The
// globe wants this (there is no edge at the antimeridian, only more world);
// the flat map does not (its frame really does end at ±180).
function landAt(col, row, grid, wrapX) {
  if (row < 0 || row >= grid.rows) return false;
  let c = col;
  if (c < 0 || c >= grid.cols) {
    if (!wrapX) return false;
    c = ((c % grid.cols) + grid.cols) % grid.cols;
  }
  const p = cellCenter(c, row, grid);
  return isLand(p.lat, p.lon);
}

// Chain directed boundary edges into closed rings. Each edge is stored under
// its start point; walking successors always terminates because every corner
// has as many outgoing as incoming edges (a cell boundary is a closed curve).
function chain(edges) {
  const from = new Map();
  for (const e of edges) {
    const key = `${e[0]},${e[1]}`;
    if (!from.has(key)) from.set(key, []);
    from.get(key).push(e);
  }

  const loops = [];
  for (const [ , bucket ] of from) {
    while (bucket.length) {
      const start = bucket.pop();
      const loop = [ [ start[0], start[1] ] ];
      let x = start[2], y = start[3];
      // Guard the walk: a malformed edge set must not spin forever.
      for (let guard = 0; guard <= edges.length; guard++) {
        loop.push([ x, y ]);
        if (x === start[0] && y === start[1]) break;
        const next = from.get(`${x},${y}`);
        if (!next?.length) break;
        const e = next.pop();
        x = e[2]; y = e[3];
      }
      if (loop.length > 2) loops.push(loop);
    }
  }
  return loops;
}

// grid: { cols, rows, latRange }. Returns { cells, loops } in GRID units —
// cells as [col, row], loop vertices as grid corners [col, row]. Renderers
// scale (flat: × CELL) or project (globe: corner → lat/lon → sphere).
export function buildLand(grid, { wrapX = false } = {}) {
  const key = `${grid.cols}|${grid.rows}|${grid.latRange[0]}|${grid.latRange[1]}|${wrapX}`;
  const hit = cache.get(key);
  if (hit) return hit;

  const cells = [];
  const edges = [];
  for (let row = 0; row < grid.rows; row++) {
    for (let col = 0; col < grid.cols; col++) {
      if (!landAt(col, row, grid, wrapX)) continue;
      cells.push([ col, row ]);
      // Clockwise with y pointing down.
      if (!landAt(col, row - 1, grid, wrapX)) edges.push([ col, row, col + 1, row ]);
      if (!landAt(col + 1, row, grid, wrapX)) edges.push([ col + 1, row, col + 1, row + 1 ]);
      if (!landAt(col, row + 1, grid, wrapX)) edges.push([ col + 1, row + 1, col, row + 1 ]);
      if (!landAt(col - 1, row, grid, wrapX)) edges.push([ col, row + 1, col, row ]);
    }
  }

  const out = { cells, loops: chain(edges) };
  cache.set(key, out);
  return out;
}

// The land styles, parsed once so both renderers agree on what a value means.
// `land` is a space-separated token list so combinations read naturally:
//   land="dots"           the dot field mappo is named for (default)
//   land="solid"          filled landmass
//   land="outline"        coastline only
//   land="solid outline"  filled, with the coast drawn on top
export function parseLandStyle(value) {
  const tokens = String(value ?? "dots").trim().toLowerCase().split(/\s+/).filter(Boolean);
  const dots = tokens.includes("dots") || tokens.length === 0;
  return {
    dots,
    fill: tokens.includes("solid") || tokens.includes("filled"),
    stroke: tokens.includes("outline") || tokens.includes("stroke")
  };
}

// Where land geometry comes from. Two levels of detail of the same world:
//
//   "grid"   — contours traced from the packed bitmask. Blocky by design,
//              resolution-following (cols changes the coastline), ~0 extra
//              bytes, and the only source the dot field can agree with.
//   "vector" — the real Natural Earth coastline, quantized to 1/32°. Smooth
//              at any size, independent of cols, ~13 KB.
//
// Both answer in rings of [lat, lon] for renderers that project (the globe);
// the flat map converts grid contours in its own units. Country borders are
// vector-only — a 512×256 raster cannot express a border that follows a
// river.
export function landRings(source) {
  return source === "vector" ? landShapes() : null;
}

export function borderRings() {
  return countryShapes();
}

// ══════════ src/noise.js ══════════
// Compact 2D value noise — smooth, deterministic, zero-dependency. Used to
// shape animation DELAY fields (animation: "noise"): neighboring dots
// get neighboring phases, so the matrix shimmers in organic patches instead
// of mechanical sweeps. Not full simplex noise — for picking per-dot delays
// once at render time, smooth value noise is indistinguishable and a third
// of the code. If a future time-evolving mode needs higher-quality gradients,
// swap the internals; the noise2(x, y) → [-1, 1] contract holds.

// Deterministic integer hash → [0, 1). Same input, same output, every load —
// re-renders must not reshuffle the field.
function hash(ix, iy) {
  let h = (ix * 374761393 + iy * 668265263) | 0; // large primes
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

// Quintic smoothstep — C2-continuous interpolation, no grid-line artifacts.
function fade(t) {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

// @return [Number] smooth noise in [-1, 1]
export function noise2(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = x - ix, fy = y - iy;

  const a = hash(ix, iy);
  const b = hash(ix + 1, iy);
  const c = hash(ix, iy + 1);
  const d = hash(ix + 1, iy + 1);

  const ux = fade(fx), uy = fade(fy);
  const value = a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  return value * 2 - 1;
}

// ══════════ src/color.js ══════════
// One color utility: the auto hover shade. When dot-hover-color isn't set,
// hovers derive from dot-color itself — darker for light dots, lighter for
// dark dots — so a custom-colored map never falls back to somebody else's
// gray. Hex in, hex out; non-hex inputs (named colors, rgb()) fall back to
// a CSS color-mix() string, which every browser that runs this component
// already supports.

export function hoverShade(color) {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color?.trim?.() ?? "");
  if (!m) return `color-mix(in srgb, ${color} 65%, black)`;
  let hex = m[1];
  if (hex.length === 3) hex = hex.replace(/./g, (ch) => ch + ch);
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  const luminance = 0.299 * r + 0.587 * g + 0.114 * b;
  const shade = luminance > 140
    ? (v) => Math.round(v * 0.62)                    // light dot → darker shade
    : (v) => Math.round(v + (255 - v) * 0.45);       // dark dot → lighter tint
  return `#${[r, g, b].map((v) => shade(v).toString(16).padStart(2, "0")).join("")}`;
}

// Resolve a CSS custom property to a concrete colour.
//
// `dot-color="var(--color-border-100)"` should Just Work: the host already
// keeps its palette in CSS variables, and asking it to duplicate those hex
// values into map attributes guarantees the two drift — most visibly the
// moment someone adds a dark mode. Accepts `var(--x)` and `var(--x, #fallback)`;
// anything else passes through untouched.
export function resolveColor(value, el) {
  if (typeof value !== "string") return value;
  const m = /^var\(\s*(--[^,)\s]+)\s*(?:,\s*([^)]+))?\)$/.exec(value.trim());
  if (!m) return value;
  if (typeof getComputedStyle !== "function") return (m[2] ?? "").trim() || "#000";

  const root = el?.ownerDocument?.documentElement
    ?? (typeof document !== "undefined" ? document.documentElement : null);
  const resolved = root ? getComputedStyle(root).getPropertyValue(m[1]).trim() : "";
  return resolved || (m[2] ?? "").trim() || "#000";
}

// Does this option bundle reference any CSS variable? Renderers use this to
// decide whether it's worth watching the document for theme changes at all —
// a map with literal hex colours pays nothing.
export function usesCssVars(...values) {
  return values.some((v) => typeof v === "string" && v.includes("var(--"));
}

