// Resolve one entry from the `cities` option: a registry name (string,
// case-insensitive) or a { name, lat, lon, … } object. Returns a normalized
// object or null for unknown names (the renderer warns, never throws — a
// typo'd city must not take down a hero section).
// "São Paulo" and "Sao Paulo" are the same place, and a person typing the
// first should not be told their city does not exist. The table stays keyed
// in plain ASCII and the LOOKUP folds instead: NFD splits a letter from its
// combining marks, and the marks go. The name you passed is what gets
// labelled — folding is how we find the city, not how we spell it back.
const fold = (name) => name.trim().normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();

export function resolveCity(entry) {
  if (typeof entry === "string") {
    const coords = CITIES[fold(entry)];
    return coords ? { name: entry.trim(), lat: coords[0], lon: coords[1] } : null;
  }
  if (entry && typeof entry.lat === "number" && typeof entry.lon === "number") {
    return { name: entry.name ?? "", ...entry };
  }
  return null;
}

// ══════════ src/highlight.js ══════════
// Region highlight: a polygon (rings of [lat, lon] pairs) tested per dot
// at geometry-build time. The consumer supplies the shape — mappo stays
// dependency-free (no bundled boundary dataset); VehiclesDB feeds it
// Natural Earth rings per jurisdiction.
//
// Ray-cast in lon/lat space. Rings that cross the antimeridian should be
// pre-normalized by the caller (shift western lons +360); normalizeRings
// below does it for rings whose lon span exceeds 180°.

export function normalizeRings(rings) {
  return rings.map((ring) => {
    let min = Infinity, max = -Infinity;
    for (const [, lon] of ring) { if (lon < min) min = lon; if (lon > max) max = lon; }
    if (max - min <= 180) return { ring, shifted: false };
    return { ring: ring.map(([la, lo]) => [la, lo < 0 ? lo + 360 : lo]), shifted: true };
  });
}

export function pointInRings(lat, lon, normalized) {
  for (const { ring, shifted } of normalized) {
    const x = shifted && lon < 0 ? lon + 360 : lon;
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [yi, xi] = ring[i];
      const [yj, xj] = ring[j];
      if ((yi > lat) !== (yj > lat) && x < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
        inside = !inside;
      }
    }
    if (inside) return true;
  }
  return false;
}

// ══════════ src/globe.js ══════════
// Globe mode: the same land grid wrapped on a sphere and spun — on canvas,
// not SVG. A rotating globe re-projects every dot every frame; SVG would
// mean thousands of DOM attribute writes at 60Hz, which is exactly the
// failure mode the flat renderer's architecture exists to avoid. Canvas
// redraws ~4k rects/frame without noticing.
//
// The visual grammar (matched to the reference the mode was built for):
// dots shrink and fade toward the limb (foreshortening reads as depth),
// the front hemisphere only (back culled), and a thin halo ring floats
// just outside the sphere. tilt doubles as the axial tilt here — the same
// option that lays the flat map down leans the globe.
//
// Node-safe: the point-buffer builders are pure and testable; GlobeRenderer
// touches the DOM only in its constructor, which only runs in a browser.


// Unit-sphere position for a lat/lon. At rotation 0, lon 0 faces the
// viewer (+z out of the screen), +y is north.
export function latLonToXYZ(lat, lon) {
  const phi = (lat * Math.PI) / 180;
  const lambda = (lon * Math.PI) / 180;
  const cosPhi = Math.cos(phi);
  return {
    x: cosPhi * Math.sin(lambda),
    y: Math.sin(phi),
    z: cosPhi * Math.cos(lambda)
  };
}

// Land dots as a flat Float32Array [x,y,z, x,y,z, …] — same grid sampling
// as the flat renderer (cellCenter + isLand), so flat and globe agree on
// what the world looks like at a given resolution.
// Per-point highlight flags, aligned index-for-index with
// buildGlobePoints (same loop, same skip rule) — the phase-array
// discipline, reused: geometry arrays never reorder, parallel arrays
// annotate.
export function buildGlobeFlags(cols, latRange, test, water = false) {
  const rows = Math.round((cols / 360) * (latRange[1] - latRange[0]));
  const grid = { cols, rows, latRange };
  const out = [];
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const c = cellCenter(col, row, grid);
      if (isLand(c.lat, c.lon) === water) continue;
      out.push(test(c.lat, c.lon) ? 1 : 0);
    }
  }
  return new Uint8Array(out);
}

export function buildGlobePoints(cols, latRange, water = false) {
  const rows = Math.round((cols / 360) * (latRange[1] - latRange[0]));
  const grid = { cols, rows, latRange };
  const out = [];
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const c = cellCenter(col, row, grid);
      if (isLand(c.lat, c.lon) === water) continue;
      const p = latLonToXYZ(c.lat, c.lon);
      out.push(p.x, p.y, p.z);
    }
  }
  return new Float32Array(out);
}

// Per-point animation phase + amplitude, aligned index-for-index with
// buildGlobePoints (same loop, same skip rule). Phase picks WHEN a dot
// moves in the cycle, amp how far — the exact fields the flat renderer
// bakes into its dot markup, so the six modes read the same on a sphere.
export function buildGlobePhases(cols, latRange, mode, water = false) {
  const rows = Math.round((cols / 360) * (latRange[1] - latRange[0]));
  const grid = { cols, rows, latRange };
  const out = [];
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const c = cellCenter(col, row, grid);
      if (isLand(c.lat, c.lon) === water) continue;
      let p;
      switch (mode) {
        case "noise":   p = (noise2(col * 0.22, row * 0.22) + 1) / 2; break;
        case "ripple":  p = Math.hypot(col - cols / 2, row - rows / 2) / Math.hypot(cols / 2, rows / 2); break;
        case "sweep":   p = col / cols; break;
        case "sparkle": p = (noise2(col * 3.7 + 9, row * 3.7 + 9) + 1) / 2; break;
        default:        p = (col + row) / (cols + rows); // wave
      }
      out.push(p, 0.55 + 0.45 * ((noise2(col * 0.31 + 47, row * 0.31 + 47) + 1) / 2));
    }
  }
  return new Float32Array(out);
}

export class GlobeRenderer {
  // @param container [HTMLElement] emptied; a square canvas fills its width.
  // @param options   [Object] the owning Mappo's options (shared ref).
  constructor(container, options) {
    this.container = container;
    this.o = options;
    // focus: start the spin facing a point — the rotation that brings
    // the focus longitude to the front (z-max at rot = -λ, since
    // latLonToXYZ puts λ=0 facing the viewer at angle 0).
    this.angle = options.focus ? ((-options.focus.lon % 360) + 360) % 360 : 0;
    this._raf = null;
    this._t = null;

    // <mappo-world> is inline by default — an inline container has
    // clientWidth 0, which turned v0.3.0's first cut into a stretched
    // ribbon (square backing store, rectangular CSS box). Two guarantees
    // fix it for good: the host becomes a block, and the canvas box is
    // aspect-locked square via CSS so display and backing store can never
    // disagree on shape.
    if (typeof getComputedStyle === "function" &&
        getComputedStyle(container).display === "inline") {
      container.style.display = "block";
    }
    // Harvest host overlay markup BEFORE the canvas replaces the
    // container's children, or replaceChildren would delete the very
    // labels the caller asked us to position. mappo adopts them: they are
    // re-parented into an absolutely-positioned layer over the canvas and
    // given a transform every frame. The host keeps ownership of
    // everything else — markup, styling, and whether they are links.
    this._overlayEls = this.o.overlays === false ? []
      : Array.from(container.querySelectorAll("[data-lat][data-lon]"));

    this.canvas = document.createElement("canvas");
    this.canvas.className = "mappo-globe";
    this.canvas.style.display = "block";
    this.canvas.style.width = "100%";
    this.canvas.style.aspectRatio = "1 / 1";
    container.replaceChildren(this.canvas);
    if (this._overlayEls.length) {
      if (getComputedStyle(container).position === "static") container.style.position = "relative";
      this._overlayLayer = document.createElement("div");
      this._overlayLayer.className = "mappo-overlay";
      // pointer-events:none on the LAYER, not the children: the layer must
      // not swallow drag-to-spin, but a label that wants to be clickable
      // only has to set pointer-events:auto on itself.
      Object.assign(this._overlayLayer.style, {
        position: "absolute", inset: "0", pointerEvents: "none"
      });
      for (const el of this._overlayEls) {
        Object.assign(el.style, { position: "absolute", left: "0", top: "0", willChange: "transform" });
        this._overlayLayer.appendChild(el);
      }
      container.appendChild(this._overlayLayer);
    }
    this.ctx = this.canvas.getContext("2d");

    this._watchTheme();

    this._rebuildData();

    // Reduced motion: one static frame, no loop. Checked once at build —
    // the OS-level setting rarely flips mid-visit.
    this._static = typeof matchMedia === "function" &&
      matchMedia("(prefers-reduced-motion: reduce)").matches;

    // Offscreen globes must not burn frames — pause when scrolled away.
    this._visible = true;
    if (typeof IntersectionObserver === "function") {
      this._io = new IntersectionObserver(([entry]) => {
        this._visible = entry.isIntersecting;
        if (this._visible && !this._raf && !this._static) {
          this._t = null; // don't let the paused gap become one giant dt
          this._loop();
        }
      });
      this._io.observe(this.canvas);
    }
    if (typeof ResizeObserver === "function") {
      // Observe the canvas itself: its CSS box (100% wide, aspect-locked
      // square) is the ground truth the backing store must match.
      this._ro = new ResizeObserver(() => this._resize());
      this._ro.observe(this.canvas);
    }

    this.#bindPointer();
    this._resize(); // sizes the canvas and draws the first frame
    if (!this._static) this._loop();
  }

  // Any option may have changed (the options object is shared with the
  // owning Mappo, so no diffing is possible here). Rebuilding the point
  // buffer is a few ms even at max resolution — just do it. The rotation
  // angle deliberately survives.
  update() {
    this._cvCache = null;
    this._land = null;
    // Re-checked on every update, not only at build: a colour can BECOME a
    // var() long after construction — a themed attribute set from JS, a knob,
    // a framework binding — and a globe that installed no observer because it
    // started out with literals would then sit at whatever the palette was
    // when it was built, and never follow the theme again.
    this._watchTheme();
    this._rebuildData();
    this._draw();
  }

  // Colours given as CSS variables follow the host's theme. Watch the document
  // element for the class/style flips theme switches are made of, drop the
  // memo, repaint. Costs nothing when every colour is a literal — no observer
  // is installed unless a var is in play, and it is disconnected again if the
  // last one goes away.
  _watchTheme() {
    const wanted = typeof MutationObserver === "function" && usesCssVars(
      this.o.dotColor, this.o.graticuleColor, this.o.equatorColor, this.o.markerColor,
      this.o.oceanColor, this.o.background, this.o.landColor, this.o.landStroke,
      this.o.bordersColor, this.o.highlightColor);
    if (wanted === !!this._themeObserver) return;
    if (!wanted) { this._themeObserver.disconnect(); this._themeObserver = null; return; }
    this._themeObserver = new MutationObserver(() => { this._cvCache = null; this._draw(); });
    this._themeObserver.observe(document.documentElement, {
      attributes: true, attributeFilter: [ "class", "style", "data-theme" ]
    });
  }

  // Resolve a colour option, memoized. `var(--x)` costs one
  // getComputedStyle the first time and nothing after, until the theme moves.
  _c(value) {
    if (typeof value !== "string" || !value.includes("var(--")) return value;
    this._cvCache ??= new Map();
    if (!this._cvCache.has(value)) this._cvCache.set(value, resolveColor(value, this.container));
    return this._cvCache.get(value);
  }

  destroy() {
    if (this._raf) cancelAnimationFrame(this._raf);
    this._raf = null;
    this._io?.disconnect();
    this._ro?.disconnect();
    this._themeObserver?.disconnect();
    this._overlayLayer?.remove();
    const c = this.canvas;
    c.removeEventListener("pointerdown", this._onDown);
    c.removeEventListener("pointermove", this._onMove);
    c.removeEventListener("pointerup", this._onUp);
    c.removeEventListener("pointercancel", this._onUp);
    c.removeEventListener("pointerleave", this._onLeave);
    c.removeEventListener("click", this._onClick);
    c.remove();
  }

  // ── pointer layer: hover/click events + drag-to-spin ─────────────────────
  // Mirrors the flat renderer's contract exactly: onDotClick/onDotEnter/
  // onCityClick/onCityEnter callbacks + bubbling mappo:* CustomEvents,
  // gated by `interactive`. On top of that, the globe is grabbable: drag
  // spins it directly, a flick carries momentum, and the spin relaxes back
  // to rotateSpeed on an exponential (~0.8s) — seamless handoff, no snap.

  // One marker/highlight footprint, honoring the shape options — the canvas
  // twin of the flat renderer's <use href="#mappo-marker-shape">.
  #drawShape(sx, sy, size, shape) {
    const ctx = this.ctx;
    if (shape === "square") {
      ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
    } else if (shape === "triangle") {
      ctx.beginPath();
      ctx.moveTo(sx, sy - size / 2);
      ctx.lineTo(sx + size / 2, sy + size / 2);
      ctx.lineTo(sx - size / 2, sy + size / 2);
      ctx.fill();
    } else if (shape === "pin") {
      // The map-pin (Google-marker silhouette): round head, tapered
      // tail, ANCHORED AT THE TIP — (sx, sy) is the place, the head
      // floats above it. A punched hole keeps it reading as a pin at
      // small sizes.
      const r = size * 0.62;
      const hy = sy - r * 1.9;      // head center
      ctx.beginPath();
      ctx.arc(sx, hy, r, Math.PI * 0.85, Math.PI * 0.15);
      ctx.quadraticCurveTo(sx + r * 0.55, hy + r * 1.1, sx, sy);
      ctx.quadraticCurveTo(sx - r * 0.55, hy + r * 1.1, sx - r * Math.cos(Math.PI * 0.15), hy + r * Math.sin(Math.PI * 0.15));
      ctx.closePath();
      ctx.fill();
      const punch = ctx.globalCompositeOperation;
      ctx.globalCompositeOperation = "destination-out";
      ctx.beginPath();
      ctx.arc(sx, hy, r * 0.42, 0, 6.2832);
      ctx.fill();
      ctx.globalCompositeOperation = punch;
    } else { // circle + custom-path fallback
      ctx.beginPath();
      ctx.arc(sx, sy, size / 2, 0, 6.2832);
      ctx.fill();
    }
  }

  #bindPointer() {
    this._drag = { active: false, moved: 0, lastX: 0, lastT: 0, v: 0 };
    this._hover = null;
    const c = this.canvas;
    this._onDown = (e) => {
      if (this.o.interactive === false) return;
      this._drag.active = true;
      this._drag.moved = 0;
      this._drag.lastX = e.clientX;
      this._drag.lastT = e.timeStamp;
      this._drag.v = 0;
      c.setPointerCapture?.(e.pointerId);
      c.style.cursor = "grabbing";
    };
    this._onMove = (e) => {
      if (this.o.interactive === false) return;
      if (this._drag.active) {
        const dx = e.clientX - this._drag.lastX;
        const dt = Math.max(1, e.timeStamp - this._drag.lastT);
        // Surface-true feel: dragging the equator by R px turns ~57°.
        const dDeg = (dx * 180) / (Math.PI * this.side * 0.40);
        this.angle = (this.angle + dDeg + 360) % 360;
        this._drag.v = 0.75 * this._drag.v + 0.25 * (dDeg / (dt / 1000));
        this._drag.moved += Math.abs(dx);
        this._drag.lastX = e.clientX;
        this._drag.lastT = e.timeStamp;
        if (this._static) this._draw();
      } else {
        this.#hover(e);
      }
    };
    this._onUp = (e) => {
      if (!this._drag.active) return;
      this._drag.active = false;
      c.releasePointerCapture?.(e.pointerId);
      c.style.cursor = "grab";
      // The flick: released velocity becomes the spin, clamped sane; the
      // loop's exponential relaxation walks it back to rotateSpeed.
      this._omega = Math.max(-360, Math.min(360, this._drag.v));
      if (this._static) this._omega = this.o.rotateSpeed; // no momentum without motion
    };
    this._onLeave = () => this.#clearHover();
    this._onClick = (e) => {
      if (this.o.interactive === false) return;
      if (this._drag.moved > 4) return; // that was a drag, not a click
      const hit = this.#hitTest(e);
      if (hit) this.#dispatch(hit.kind, "Click", hit.detail);
    };
    c.addEventListener("pointerdown", this._onDown);
    c.addEventListener("pointermove", this._onMove);
    c.addEventListener("pointerup", this._onUp);
    c.addEventListener("pointercancel", this._onUp);
    c.addEventListener("pointerleave", this._onLeave);
    c.addEventListener("click", this._onClick);
  }

  #hover(e) {
    const hit = this.#hitTest(e);
    const key = hit ? `${hit.kind}:${hit.detail.name ?? `${hit.detail.col},${hit.detail.row}`}` : null;
    if (key === this._hoverKey) return;
    this._hoverKey = key;
    this._hover = hit;
    this.canvas.style.cursor = hit
      ? (hit.kind === "city" ? this.o.markerCursor : this.o.cursor)
      : "grab";
    if (hit) this.#dispatch(hit.kind, "Enter", hit.detail);
    if (this._static) this._draw();
  }

  #clearHover() {
    if (!this._hover) return;
    this._hover = null;
    this._hoverKey = null;
    this.canvas.style.cursor = this.o.interactive === false ? "" : "grab";
    if (this._static) this._draw();
  }

  // Screen point → sphere surface → lat/lon → grid cell (or city, checked
  // first in screen space since markers draw on top).
  #hitTest(e) {
    const rect = this.canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    const side = this.side;
    const cx = side / 2, cy = side / 2, R = side * 0.40;
    const rot = (this.angle * Math.PI) / 180;
    const tilt = ((this.o.tilt || 0) * Math.PI) / 180;
    const sinR = Math.sin(rot), cosR = Math.cos(rot);
    const sinT = Math.sin(tilt), cosT = Math.cos(tilt);
    // Un-roll the pointer first: roll is applied last when drawing, so it
    // is undone first when inverting. Everything below then works in the
    // unrolled frame exactly as it did before roll existed.
    const roll = ((this.o.roll || 0) * Math.PI) / 180;
    const sinRo = Math.sin(-roll), cosRo = Math.cos(-roll);
    const rdx = mx - cx, rdy = my - cy;
    const ux = cx + rdx * cosRo - rdy * sinRo;
    const uy = cy + rdx * sinRo + rdy * cosRo;
    const base = Math.max(0.75, (4 * R) / (this.o.cols ?? 170)) * this.o.dotSize * 1.6;

    for (const city of this.cityData) {
      const x1 = city.p.x * cosR + city.p.z * sinR;
      const z1 = -city.p.x * sinR + city.p.z * cosR;
      const y2 = city.p.y * cosT - z1 * sinT;
      const z2 = city.p.y * sinT + z1 * cosT;
      if (z2 <= 0.01) continue;
      if (Math.hypot(ux - (cx + x1 * R), uy - (cy - y2 * R)) <= Math.max(10, base * this.o.markerScale * 0.9)) {
        return { kind: "city", detail: { name: city.name, lat: city.lat, lon: city.lon, element: this.canvas } };
      }
    }

    const X = (ux - cx) / R;
    const Y = -(uy - cy) / R;
    const rr = X * X + Y * Y;
    if (rr > 1) return null;
    const Z = Math.sqrt(1 - rr);
    // Inverse of the draw transform: un-tilt, then un-spin.
    const y = Y * cosT + Z * sinT;
    const z1 = -Y * sinT + Z * cosT;
    const x = X * cosR - z1 * sinR;
    const z = X * sinR + z1 * cosR;
    const lat = (Math.asin(y) * 180) / Math.PI;
    const lon = (Math.atan2(x, z) * 180) / Math.PI;

    const [latMin, latMax] = this.o.latRange;
    if (lat < latMin || lat > latMax) return null;
    const cols = this.o.cols ?? 170; // auto: globes want density — foreshortening thins the limb
    const rows = Math.round((cols / 360) * (latMax - latMin));
    const col = Math.min(cols - 1, Math.max(0, Math.floor(((lon + 180) / 360) * cols)));
    const row = Math.min(rows - 1, Math.max(0, Math.floor(((latMax - lat) / (latMax - latMin)) * rows)));
    const c = cellCenter(col, row, { cols, rows, latRange: this.o.latRange });
    if (!isLand(c.lat, c.lon)) return null;
    return { kind: "dot", detail: { lat: c.lat, lon: c.lon, col, row, element: this.canvas } };
  }

  #dispatch(kind, phase, detail) {
    if (this.o.interactive === false) return;
    const cb = this.o[`on${kind === "city" ? "City" : "Dot"}${phase}`];
    if (cb) cb(detail);
    this.container.dispatchEvent(new CustomEvent(
      `mappo:${kind}${phase.toLowerCase()}`,
      { detail, bubbles: true }
    ));
  }

  _rebuildData() {
    const cols = this.o.cols ?? 170; // auto: globes want density — foreshortening thins the limb
    this.points = buildGlobePoints(cols, this.o.latRange);
    // The graticule is pure lat/lon geometry — built once per option change,
    // projected per frame. Cheap enough to rebuild unconditionally.
    this._graticule = this.o.graticule
      ? buildGraticule({ meridians: this.o.meridians, parallels: this.o.parallels })
      : null;
    // Region highlight: flags parallel the land points (never reorder
    // geometry — annotate it).
    if (this.o.highlightPolygon?.length) {
      const normalized = normalizeRings(this.o.highlightPolygon);
      this.highlightFlags = buildGlobeFlags(cols, this.o.latRange, (lat, lon) => pointInRings(lat, lon, normalized));
    } else {
      this.highlightFlags = null;
    }
    this.waterPoints = this.o.oceanColor && this.o.oceanColor !== "none"
      ? buildGlobePoints(cols, this.o.latRange, true)
      : null;
    this.phases = this.o.animation && this.o.animation !== "none"
      ? buildGlobePhases(cols, this.o.latRange, this.o.animation)
      : null;
    const resolved = [ ...(this.o.cities || []), ...(this.o.markers || []) ]
      .map((c) => (typeof c === "string" ? resolveCity(c) : resolveCity(c)))
      .filter(Boolean);
    this.cityData = resolved.map((c) => ({ name: c.name, lat: c.lat, lon: c.lon, p: latLonToXYZ(c.lat, c.lon) }));
    this.canvas.style.cursor = this.o.interactive === false ? "" : "grab";
    if (this.o.dotShape !== "circle" && this.o.dotShape !== "square" &&
        this.o.dotShape !== "triangle" && !this._shapeWarned) {
      this._shapeWarned = true;
      console.warn(`[mappo] mode="globe" draws circle/square/triangle dots; custom SVG paths fall back to squares`);
    }
  }

  _resize() {
    const rect = this.canvas.getBoundingClientRect();
    const side = rect.width || this.container.clientWidth || 300;
    // Cap the backing store. A 3× phone painting a 400px globe would other-
    // wise allocate 1200² and burn the fill rate for detail no eye resolves;
    // 2 is where the returns stop on a dot field. (Cloudflare's WebGL globe
    // caps at the same number, and pins mobile to 1.)
    const raw = (typeof devicePixelRatio === "number" && devicePixelRatio) || 1;
    const dpr = Math.min(raw, this.o.maxDpr ?? 2);
    this.side = side;
    this.canvas.width = Math.max(1, Math.round(side * dpr));
    this.canvas.height = Math.max(1, Math.round(side * dpr));
    this._dpr = dpr;
    this._draw();
  }

  _loop() {
    this._raf = requestAnimationFrame((t) => {
      this._raf = null;
      if (!this._visible) return; // the IntersectionObserver restarts us
      const dt = this._t == null ? 16 : Math.min(100, t - this._t);
      this._t = t;
      this._time = (this._time || 0) + dt / 1000;
      if (this._drag?.active) {
        // The pointer owns the angle while dragging.
      } else {
        if (this._omega == null) this._omega = this.o.rotateSpeed;
        // Momentum relaxes back to the base spin — exponential, ~0.8s to
        // settle, so the handoff from a flick to auto-rotation is seamless.
        this._omega += (this.o.rotateSpeed - this._omega) * (1 - Math.exp(-dt / 800));
        this.angle = (this.angle + (this._omega * dt) / 1000 + 360) % 360;
      }
      this._draw();
      this._loop();
    });
  }

  // One transformed, culled, depth-faded pass over a point buffer — land
  // and water share it; only color, size and alpha band differ.
  // One place that knows how a lat/lon becomes a pixel on this sphere.
  // The dot loop keeps its own inlined copy (it runs tens of thousands of
  // times a frame and every property read shows up); everything else —
  // graticule, DOM overlays, future arcs — goes through here so there is a
  // single definition of the transform to keep correct.
  #project(lat, lon, { cx, cy, R, sinR, cosR, sinT, cosT, sinRo = 0, cosRo = 1 }) {
    const p = latLonToXYZ(lat, lon);
    const x1 = p.x * cosR + p.z * sinR;
    const z1 = -p.x * sinR + p.z * cosR;
    const y2 = p.y * cosT - z1 * sinT;
    const z2 = p.y * sinT + z1 * cosT;
    const dx = x1 * R, dy = -y2 * R;
    return {
  sx: cx + dx * cosRo - dy * sinRo,
  sy: cy + dx * sinRo + dy * cosRo,
  z: z2, front: z2 > 0.01
    };
  }

  // Vector land on the sphere: real coastlines, clipped to the visible hemisphere.
  //
  // Stroking is easy — break the polyline whenever it turns away, exactly like
  // the graticule. FILLING is the hard part, and the reason a naive version
  // looks broken: in an orthographic projection the far side of the world folds
  // onto the near side, so feeding a whole ring to fill() paints a mirrored
  // ghost across the disc. Culling the back points instead leaves the ring open,
  // and an open ring fills to a straight chord — slicing a bite out of every
  // continent that touches the limb.
  //
  // The fix is to CLOSE each ring along the limb: walk the ring, keep the runs
  // that face us, and join consecutive runs with an arc of the sphere's own
  // silhouette. That is what the eye expects, because it is what the horizon
  // actually is.
  #drawVectorLand(T, style, rings, { fill, stroke, width, alphaScale = 1 }) {
    const ctx = this.ctx;
    const { cx, cy, R } = T;

    if (fill) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.clip();                       // nothing may paint outside the planet
      ctx.fillStyle = fill;
    }

    for (const ring of rings) {
      const pts = ring.map(([ lat, lon ]) => this.#project(lat, lon, T));
      // Fill is deliberately NOT drawn from these rings. Clipping a spherical
      // polygon to the visible hemisphere analytically is a genuinely hard
      // problem, and every cheap rule for rejoining the clipped runs along the
      // limb was measured painting open ocean: the shorter arc closes a wide
      // run around the wrong side; the exit tangent sends a single-run ring the
      // long way round the disc; one constant direction per ring inverts the
      // whole thing. (A pixel probe over 24 rotations scored them: 38, 35 and
      // 98 ocean samples wrongly filled.) The globe therefore fills from the
      // mask — see #drawLand — which culls cell by cell and cannot fail that
      // way, and these rings draw the coastline on top.

      // Depth-banded, for the same reason the graticule is: a single stroke()
      // can only carry one alpha, so a per-point globalAlpha silently paints
      // each coastline at the tone of its final vertex.
      if (stroke) this.#strokeBanded([ pts ], stroke, width, 1, alphaScale);
    }

    if (fill) ctx.restore();
    ctx.globalAlpha = 1;
  }

  // Fill one ring, clipped to the visible hemisphere.
  //
  // The rule that makes this correct: when you clip a polygon to a disc and
  // keep the INSIDE, the disc's boundary is always traversed in ONE direction
  // for that polygon — the same direction the polygon itself is wound. Deciding
  // it per crossing (from the exit tangent) is what sent single-run rings the
  // long way round and filled open ocean; so the direction is settled once, for
  // the whole ring, from the ring's own orientation, and every bridge obeys it.
  //
  // Runs are then joined exit → NEXT ENTRY BY ANGLE in that direction, never in
  // array order: Afro-Eurasia crosses the silhouette fourteen times in a single
  // ring, and those crossings do not arrive in the order they sit around the
  // limb.
  #fillClippedRing(ring, pts, T, alphaScale) {
    const ctx = this.ctx;
    const { cx, cy, R } = T;
    const n = pts.length;
    const TAU = Math.PI * 2;
    if (!pts.some((p) => p.front)) return;

    const paint = (depth) => {
      ctx.globalAlpha = (0.4 + 0.6 * depth) * alphaScale;
      ctx.fill();
    };

    if (pts.every((p) => p.front)) {
      ctx.beginPath();
      ctx.moveTo(pts[0].sx, pts[0].sy);
      for (let i = 1; i < n; i++) ctx.lineTo(pts[i].sx, pts[i].sy);
      ctx.closePath();
      paint(pts[0].z);
      return;
    }

    const crossing = (i, j) => {
      const t = pts[i].z / (pts[i].z - pts[j].z);
      let lon0 = ring[i][1], lon1 = ring[j][1];
      if (lon1 - lon0 > 180) lon1 -= 360; else if (lon0 - lon1 > 180) lon1 += 360;
      return this.#project(ring[i][0] + (ring[j][0] - ring[i][0]) * t,
                           lon0 + (lon1 - lon0) * t, T);
    };

    let startAt = 0;
    for (let i = 0; i < n; i++) {
      if (pts[i].front && !pts[(i - 1 + n) % n].front) { startAt = i; break; }
    }

    const runs = [];
    let current = null;
    let signed = 0;                      // shoelace over the VISIBLE geometry
    for (let k = 0; k < n; k++) {
      const i = (startAt + k) % n;
      const prev = (i - 1 + n) % n;
      if (pts[i].front) {
        if (!current) current = [ crossing(i, prev) ];
        current.push(pts[i]);
      } else if (current) {
        current.push(crossing(prev, i));
        for (let m = 0; m < current.length - 1; m++) {
          signed += (current[m].sx - cx) * (current[m + 1].sy - cy)
                  - (current[m + 1].sx - cx) * (current[m].sy - cy);
        }
        runs.push(current);
        current = null;
      }
    }
    if (current) runs.push(current);
    if (!runs.length) return;

    // One direction for the whole ring, taken from its own winding on screen.
    const dir = signed >= 0 ? 1 : -1;
    const angleOf = (p) => Math.atan2(p.sy - cy, p.sx - cx);
    for (const r of runs) {
      r.inAngle = angleOf(r[0]);
      r.outAngle = angleOf(r[r.length - 1]);
      r.used = false;
    }
    const sweep = (from, to) => {
      let d = dir > 0 ? to - from : from - to;
      d = ((d % TAU) + TAU) % TAU;
      return dir > 0 ? d : -d;
    };

    for (const seed of runs) {
      if (seed.used) continue;
      ctx.beginPath();
      ctx.moveTo(seed[0].sx, seed[0].sy);
      let run = seed, guard = 0;
      while (run && !run.used && guard++ <= runs.length) {
        run.used = true;
        for (let i = 1; i < run.length; i++) ctx.lineTo(run[i].sx, run[i].sy);
        let next = null, bestGap = Infinity;
        for (const r of runs) {
          if (r.used) continue;
          const gap = Math.abs(sweep(run.outAngle, r.inAngle));
          if (gap < bestGap) { bestGap = gap; next = r; }
        }
        const target = next ?? seed;
        ctx.arc(cx, cy, R, run.outAngle, run.outAngle + sweep(run.outAngle, target.inAngle),
                sweep(run.outAngle, target.inAngle) < 0);
        if (!next) break;
        run = next;
      }
      ctx.closePath();
      paint(seed[0].z);
    }
  }


  // Land as shape on the sphere — the same land.js geometry the flat map uses.
  //
  // The two halves are drawn differently ON PURPOSE, because a sphere is not a
  // plane:
  //
  //   fill    — per-cell quads. A closed coastline loop that crosses the limb
  //             cannot be filled correctly (half of it is on the far side and
  //             the ring is no longer closed in screen space). Projected quads
  //             tile edge-to-edge into the same landmass and cull individually,
  //             so the limb is handled by simply not drawing what faces away.
  //   outline — the contour loops, stroked and broken at the limb, exactly like
  //             the graticule. A coastline is a line, so it has no such problem.
  //
  // Same source geometry, same option names, same result to the eye.
  #drawLand(T, style) {
    const o = this.o;
    const ctx = this.ctx;
    // Vector source: real outlines, no grid involved.
    const vector = landRings(o.landSource);
    // A FILLED globe stays on the grid, even when vector data is asked for.
    //
    // Not a preference — a consistency requirement. The vector coastline is
    // 1/32° detailed; the mask the fill comes from is 512×256. Drawing one
    // inside the other leaves white slivers all down the European coast,
    // because they are the same geography at twenty-five times the detail.
    // Until vector fills can be clipped to the hemisphere properly (see
    // #drawVectorLand), a filled globe draws BOTH fill and coast from the
    // grid, where they agree by construction. `land="outline"` with vector is
    // unaffected and is the sharpest the globe gets.
    if (vector && !style.fill) {
      this.#drawVectorLand(T, style, vector, {
        fill: null,
        stroke: style.stroke ? this._c(o.landStroke ?? o.landColor ?? o.dotColor) : null,
        width: o.landStrokeWidth ?? 1
      });
      if (o.borders) {
        this.#drawVectorLand(T, { fill: false, stroke: true }, borderRings(), {
          fill: null,
          stroke: this._c(o.bordersColor ?? o.landStroke ?? o.dotColor),
          width: o.bordersWidth ?? 0.5,
          alphaScale: o.bordersOpacity ?? 0.55
        });
      }
      return;
    }
    // Borders are lines, so they clip cleanly and can ride any fill.
    if (o.borders && vector) {
      this.#drawVectorLand(T, { fill: false, stroke: true }, borderRings(), {
        fill: null,
        stroke: this._c(o.bordersColor ?? o.landStroke ?? o.dotColor),
        width: o.bordersWidth ?? 0.5,
        alphaScale: o.bordersOpacity ?? 0.55
      });
    }
    // Resolution stays at `cols`, deliberately. Sampling the fill finer than
    // the dot grid does buy smoother coastlines, but it multiplies the quads
    // projected every frame — measured as visible stutter on a page carrying
    // several globes, which is a worse defect than a stepped coast. Turn the
    // knob with `cols` if a particular map wants the detail and can pay.
    const cols = o.cols ?? 170;
    const rows = Math.round((cols / 360) * (o.latRange[1] - o.latRange[0]));
    const grid = { cols, rows, latRange: o.latRange };
    // wrapX: on a globe there is no edge at the antimeridian, only more world.
    this._land ??= buildLand(grid, { wrapX: true });

    if (style.fill) {
      // Batched by depth band, NOT one fill() per cell.
      //
      // The land is a few thousand quads; issuing a beginPath/fill for each
      // was measured at ~13 ms per globe, which turns a page carrying several
      // of them into a slideshow. Path construction is nearly free — it is the
      // fill calls that cost — so the quads are accumulated into a handful of
      // paths, one per slice of the depth fade, and each is filled once. Same
      // picture, BANDS draw calls instead of thousands.
      const BANDS = 6;
      const paths = Array.from({ length: BANDS }, () => new Path2D());
      let any = false;
      for (const [ col, row ] of this._land.cells) {
        const a = cellCorner(col, row, grid);
        const pa = this.#project(a.lat, a.lon, T);
        if (!pa.front) continue;
        const b = cellCorner(col + 1, row, grid);
        const c = cellCorner(col + 1, row + 1, grid);
        const d = cellCorner(col, row + 1, grid);
        const pb = this.#project(b.lat, b.lon, T);
        const pc = this.#project(c.lat, c.lon, T);
        const pd = this.#project(d.lat, d.lon, T);
        if (!pb.front || !pc.front || !pd.front) continue;
        const band = Math.min(BANDS - 1, Math.floor(pa.z * BANDS));
        const path = paths[band];
        path.moveTo(pa.sx, pa.sy);
        path.lineTo(pb.sx, pb.sy);
        path.lineTo(pc.sx, pc.sy);
        path.lineTo(pd.sx, pd.sy);
        path.closePath();
        any = true;
      }
      if (any) {
        ctx.fillStyle = this._c(o.landColor ?? o.dotColor);
        for (let i = 0; i < BANDS; i++) {
          ctx.globalAlpha = 0.35 + 0.65 * ((i + 0.5) / BANDS);   // the fade the dots wear
          ctx.fill(paths[i]);
        }
      }
    }

    if (style.stroke) {
      ctx.strokeStyle = this._c(o.landStroke ?? o.landColor ?? o.dotColor);
      ctx.lineWidth = o.landStrokeWidth ?? 1;
      ctx.lineJoin = "round";
      for (const loop of this._land.loops) {
        let drawing = false;
        for (const [ col, row ] of loop) {
          const g = cellCorner(col, row, grid);
          const p = this.#project(g.lat, g.lon, T);
          if (!p.front) {
            if (drawing) { ctx.stroke(); drawing = false; }
            continue;
          }
          if (!drawing) { ctx.beginPath(); ctx.moveTo(p.sx, p.sy); drawing = true; }
          else ctx.lineTo(p.sx, p.sy);
          ctx.globalAlpha = 0.3 + 0.7 * p.z;
        }
        if (drawing) ctx.stroke();
      }
    }
    ctx.globalAlpha = 1;
  }

  // The graticule, stroked as polylines that break at the limb.
  //
  // Depth is carried by ALPHA rather than by clipping alone: a meridian
  // fades as it turns away, which is what stops the front and back of the
  // same circle from reading as one flat ellipse. The equator is stroked
  // last and separately — it is the line a reader orients against, so it
  // gets its own colour and weight instead of being one of eleven.
  #drawGraticule(T) {
    const o = this.o;
    if (!o.graticule || !this._graticule) return;
    const ctx = this.ctx;
    const color = this._c(o.graticuleColor ?? o.dotColor);
    const equator = this._c(o.equatorColor ?? o.graticuleColor ?? o.dotColor);

    const project = (lines) => lines.map((line) => line.map(([ lat, lon ]) => this.#project(lat, lon, T)));
    this.#strokeBanded(project(this._graticule.meridians), color, 1, o.graticuleOpacity);
    this.#strokeBanded(project(this._graticule.parallels), color, 1, o.graticuleOpacity);
    this.#strokeBanded(project([ this._graticule.equator ]), equator, 1, o.equatorOpacity);
  }

  // Stroke polylines with a depth fade that is actually per-segment.
  //
  // The obvious way is wrong in a way that is easy to miss: setting
  // ctx.globalAlpha inside the point loop and calling stroke() once at the end
  // does NOT fade the line, because canvas reads globalAlpha when you stroke,
  // not when you add a point. Every polyline came out flat-toned at whatever
  // alpha its LAST vertex happened to set — which is why one coastline looked
  // dark, its neighbour looked faint, and half the Pacific's meridians differed
  // from the other half. Arbitrary, and it moved as the globe turned.
  //
  // So segments are bucketed by depth and each bucket is stroked once. Same
  // fade, honestly applied, and far fewer draw calls than stroking per segment.
  #strokeBanded(lines, color, width, peak, alphaScale = 1) {
    const ctx = this.ctx;
    const BANDS = 7;
    const paths = Array.from({ length: BANDS }, () => new Path2D());
    let any = false;
    for (const pts of lines) {
      for (let i = 0; i + 1 < pts.length; i++) {
        const a = pts[i], b = pts[i + 1];
        if (!a.front || !b.front) continue;     // the far side, or crossing it
        const band = Math.min(BANDS - 1, Math.max(0, Math.floor(((a.z + b.z) / 2) * BANDS)));
        paths[band].moveTo(a.sx, a.sy);
        paths[band].lineTo(b.sx, b.sy);
        any = true;
      }
    }
    if (!any) return;
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";                       // keeps segments reading as one line
    for (let i = 0; i < BANDS; i++) {
      ctx.globalAlpha = peak * (0.25 + 0.75 * ((i + 0.5) / BANDS)) * alphaScale;
      ctx.stroke(paths[i]);
    }
    ctx.globalAlpha = 1;
  }

  // Position host-supplied DOM against the sphere.
  //
  // mappo writes ONE thing per element — a translate3d on the element that
  // carries data-lat/data-lon — and publishes depth as a custom property.
  // It deliberately does not touch scale, opacity or transition: those belong
  // to the host's own stylesheet, and an element whose position is rewritten
  // every frame must not also carry an eased transform, or the two fight.
  // The documented pattern is therefore a positioned root with a freely
  // styled child inside it.
  #placeOverlays(T) {
    if (this.o.overlays === false || !this._overlayEls) return;
    for (const el of this._overlayEls) {
      const lat = Number(el.dataset.lat);
      const lon = Number(el.dataset.lon);
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
      const p = this.#project(lat, lon, T);
      // Park far offscreen rather than hiding: no reflow, no flash at the
      // origin before the first projection lands.
      el.style.transform = p.front
        ? `translate3d(${p.sx.toFixed(2)}px, ${p.sy.toFixed(2)}px, 0)`
        : "translate3d(-9999px, -9999px, 0)";
      el.style.setProperty("--mappo-depth", p.front ? p.z.toFixed(3) : "0");
      el.toggleAttribute("data-mappo-behind", !p.front);
    }
  }

  #drawPoints(pts, { cx, cy, R, sinR, cosR, sinT, cosT, sinRo = 0, cosRo = 1, base, shape, alphaLo, alphaHi, anim, flags, baseColor, hiColor }) {
    const ctx = this.ctx;
    let currentHi = null;
    for (let i = 0; i < pts.length; i += 3) {
      // Region highlight: per-dot colour switch, batched (fillStyle only
      // changes when the flag flips — dots stream in row order, so runs
      // are long and the switch is cheap).
      if (flags) {
        const hi = flags[i / 3] === 1;
        if (hi !== currentHi) {
          ctx.fillStyle = hi ? hiColor : baseColor;
          currentHi = hi;
        }
      }
      // Spin around the polar axis, then lean by the axial tilt.
      const x1 = pts[i] * cosR + pts[i + 2] * sinR;
      const z1 = -pts[i] * sinR + pts[i + 2] * cosR;
      const y2 = pts[i + 1] * cosT - z1 * sinT;
      const z2 = pts[i + 1] * sinT + z1 * cosT;
      if (z2 <= 0.01) continue; // back hemisphere

      let lift = 0, sizeMul = 1;
      if (anim) {
        const j = (i / 3) * 2;
        const d = (anim.cycle - anim.phases[j] + 1) % 1;
        if (d < anim.w) {
          const bump = Math.sin(Math.PI * (d / anim.w)) * anim.phases[j + 1];
          if (anim.mode === "sparkle") sizeMul = 1 + 0.45 * bump;
          else lift = (anim.heightPx * bump) / R;
        }
      }
    const k = 1 + lift;
    const dx = x1 * R * k, dy = -y2 * R * k;
    const sx = cx + dx * cosRo - dy * sinRo;
    const sy = cy + dx * sinRo + dy * cosRo;
      const s = base * (0.45 + 0.55 * z2) * sizeMul; // foreshortening at the limb
      ctx.globalAlpha = alphaLo + alphaHi * z2; // …and a depth fade
      if (shape === "circle") {
        ctx.beginPath();
        ctx.arc(sx, sy, s / 2, 0, 6.2832);
        ctx.fill();
      } else if (shape === "triangle") {
        ctx.beginPath();
        ctx.moveTo(sx, sy - s / 2);
        ctx.lineTo(sx + s / 2, sy + s / 2);
        ctx.lineTo(sx - s / 2, sy + s / 2);
        ctx.fill();
      } else {
        ctx.fillRect(sx - s / 2, sy - s / 2, s, s);
      }
    }
  }

  _draw() {
    const { ctx, side } = this;
    if (!ctx || !side) return;
    const o = this.o;
    ctx.setTransform(this._dpr, 0, 0, this._dpr, 0, 0);
    ctx.clearRect(0, 0, side, side);

    const cx = side / 2;
    const cy = side / 2;
    const R = side * 0.40; // breathing room — the halo must not kiss the edges

    // Solid planet: a uniform disc behind the dots.
    if (o.background && o.background !== "none") {
      ctx.beginPath();
      ctx.arc(cx, cy, R * 1.02, 0, Math.PI * 2);
      ctx.fillStyle = this._c(o.background);
      ctx.fill();
    }

    // The halo: a hairline orbit just outside the sphere. Optional.
    if (o.globeRing !== false) {
      ctx.beginPath();
      ctx.arc(cx, cy, R * 1.08, 0, Math.PI * 2);
      ctx.strokeStyle = this._c(o.dotColor);
      ctx.globalAlpha = 0.35;
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    const rot = (this.angle * Math.PI) / 180;
    const tilt = ((o.tilt || 0) * Math.PI) / 180;
    const sinR = Math.sin(rot), cosR = Math.cos(rot);
    const sinT = Math.sin(tilt), cosT = Math.cos(tilt);
    // roll: the LEAN. tilt leans the axis away from the viewer (a
    // foreshortening, in 3D); roll turns the finished disc in the plane of
    // the screen, which is the "globe sitting at an angle" look. They are
    // different gestures and compose — so roll is applied last, to the
    // projected point, where it is a plain 2D rotation about the centre.
    const roll = ((o.roll || 0) * Math.PI) / 180;
    const sinRo = Math.sin(roll), cosRo = Math.cos(roll);

    const T = { cx, cy, R, sinR, cosR, sinT, cosT, sinRo, cosRo };

    // Graticule under the dots: it is the grid the world sits on, not an
    // overlay drawn across it.
    this.#drawGraticule(T);

    // Dot footprint ≈ visible cell spacing: cols spans 360° of longitude,
    // so the front hemisphere shows cols/2 dots across 2R.
    const base = Math.max(0.75, (4 * R) / (o.cols ?? 170)) * o.dotSize * 1.6;
    const shape = o.dotShape === "circle" || o.dotShape === "triangle" ? o.dotShape : "square";

    // Water first — smaller, dimmer, same transform — so land reads on top.
    // Water never animates: the ocean is ground, the land is figure.
    if (this.waterPoints) {
      ctx.fillStyle = this._c(o.oceanColor);
      this.#drawPoints(this.waterPoints, { cx, cy, R, sinR, cosR, sinT, cosT, sinRo, cosRo, base: base * 0.62, shape, alphaLo: 0.15, alphaHi: 0.55 });
    }

    // The six animation modes on a sphere: the phase/amp fields decide when
    // and how far each dot lifts RADIALLY off the surface (sparkle scales
    // size instead) — the canvas twin of the flat renderer's translateY.
    const anim = !this._static && o.animation && o.animation !== "none" && this.phases ? {
      mode: o.animation,
      cycle: ((this._time || 0) / o.animationPeriod) % 1,
      w: Math.min(0.9, Math.max(0.02, o.animationWidth *
        ({ ripple: 0.8, sweep: 0.5, sparkle: 0.55 }[o.animation] ?? 1))),
      heightPx: o.animationHeight * (4 * R) / (o.cols ?? 170),
      phases: this.phases
    } : null;

    const landStyle = parseLandStyle(o.land);
    if (landStyle.dots) {
      ctx.fillStyle = this._c(o.dotColor);
      this.#drawPoints(this.points, { cx, cy, R, sinR, cosR, sinT, cosT, sinRo, cosRo, base, shape, alphaLo: 0.25, alphaHi: 0.75, anim,
        flags: this.highlightFlags, baseColor: this._c(o.dotColor), hiColor: this._c(o.highlightColor) });
    } else {
      this.#drawLand(T, landStyle);
    }

    // Hovered dot re-draws bigger in the hover color (cheap overdraw).
    if (this._hover?.kind === "dot") {
      const hp = latLonToXYZ(this._hover.detail.lat, this._hover.detail.lon);
      const x1 = hp.x * cosR + hp.z * sinR;
      const z1 = -hp.x * sinR + hp.z * cosR;
      const y2 = hp.y * cosT - z1 * sinT;
      const z2 = hp.y * sinT + z1 * cosT;
      if (z2 > 0.01) {
        ctx.fillStyle = this._c(o.dotHoverColor) ?? hoverShade(this._c(o.dotColor));
        ctx.globalAlpha = 1;
    const s = base * (0.45 + 0.55 * z2) * o.dotHoverScale;
    const hdx = x1 * R, hdy = -y2 * R;
    this.#drawShape(cx + hdx * cosRo - hdy * sinRo, cy + hdx * sinRo + hdy * cosRo, s, shape);
      }
    }

    // City markers ride the same transform, drawn on top at full strength;
    // the hovered one swells by markerHoverScale.
    ctx.fillStyle = this._c(o.markerColor);
    for (const city of this.cityData) {
      const x1 = city.p.x * cosR + city.p.z * sinR;
      const z1 = -city.p.x * sinR + city.p.z * cosR;
      const y2 = city.p.y * cosT - z1 * sinT;
      const z2 = city.p.y * sinT + z1 * cosT;
      if (z2 <= 0.01) continue;
      const hovered = this._hover?.kind === "city" && this._hover.detail.name === city.name;
      ctx.globalAlpha = 1;
      const ms = base * o.markerScale * 0.6 * (hovered ? o.markerHoverScale : 1);
    const mshape = ["circle", "square", "triangle", "pin"].includes(o.markerShape) ? o.markerShape : "circle";
    const mdx = x1 * R, mdy = -y2 * R;
    this.#drawShape(cx + mdx * cosRo - mdy * sinRo, cy + mdx * sinRo + mdy * cosRo, ms * 2, mshape);
    }
    ctx.globalAlpha = 1;

    // DOM last: the overlay reads the same transform the frame just drew,
    // so labels can never lag the sphere by a frame.
    this.#placeOverlays(T);
  }
}

// ══════════ src/renderer.js ══════════
// The renderer: one land mask in, one interactive <svg> out.
//
// Design decisions worth knowing before changing things:
//
// - The FLAT map is SVG on purpose: dots stay real elements — CSS hover, focusable markers,
//   restylable from outside. Sensible up to ~250 cols; beyond that a canvas
//   renderer (same options object) is the plan.
//
// - POSITIONING: every dot/marker is `<g transform="translate(x,y)"><use/></g>`
//   and ALL animation (hover, pulse, shimmer) transforms the INNER element,
//   whose shapes are centered on the local origin. Never scale an element
//   that carries x/y geometry: the scale multiplies the translate and dots
//   fly diagonally instead of growing in place (transform-box: fill-box is
//   not reliable on <use> cross-browser).
//
// - DIFFERENTIAL UPDATES — the crash lesson. Rebuilding the world per
//   option change froze and eventually OOM-killed tabs: each rebuild parses
//   thousands of nodes, recalcs style/layout for all of them, re-registers
//   every infinite animation, and discards ~1MB of DOM for GC — and a
//   slider drag asks for that 60×/second. So update() classifies changed
//   keys and does the CHEAPEST sufficient thing:
//     · style keys  (colors, tilt, cursors, animation…) → rewrite ONE
//       persistent <style> element. No DOM touched.
//     · def keys    (dotShape/dotSize/markerShape/markerScale) → replace
//       two <defs> children; every <use> updates for free.
//     · marker keys (cities, markerPulse) → rebuild only the markers group.
//     · geometry    (cols, latRange, interactive) → full rebuild, but
//       leading+trailing debounced to ≥150ms spacing, with an LRU cache of
//       dot-markup strings per resolution (dragging back and forth replays
//       cached geometry instead of recomputing it).
//   Animation phases (--mappo-pw wave / --mappo-pn noise) are baked into every dot
//   at build time and consumed via calc() in CSS, so animation mode AND
//   duration are pure style patches too. Negative animation-delays start
//   each dot mid-cycle — no synchronized flash on load.
//
// - Events are DELEGATED from the svg root (three listeners total), never
//   per-dot. Payload coordinates come from data attributes on the wrapper.
//
// - The tilt lives on a WRAPPER div around the svg — the svg itself stays
//   untransformed so consumer getBoundingClientRect math keeps working.


export const DEFAULTS = {
  // Shape of the world: "flat" (SVG plane) or "globe" (rotating canvas
  // sphere — tilt becomes the axial tilt; hover/click and animation are
  // flat-only for now).
  mode: "flat",
  rotateSpeed: 4,             // globe spin, degrees per second (0 = still)
  globeRing: false,           // opt-in hairline halo around the globe
  // Backdrop (both modes)
  background: "none",         // uniform fill behind everything (flat rect / globe disc)
  oceanColor: "none",         // water cells as filler dots, e.g. "#e8eef5"; "none" = off
  // Grid
  cols: null,                 // auto: 120 flat · 170 globe (hard max 260); set to override
  latRange: [-58, 84],        // cut Antarctica + arctic emptiness
  // Dots
  dotShape: "circle",         // "circle" | "square" | "triangle" | an SVG path string (24×24 units)
  dotSize: 0.55,              // fraction of a grid cell the dot fills
  dotColor: "#d3dce6",
  dotHoverColor: null,        // auto: a contrast-aware shade of dotColor (darker for light dots, lighter for dark)
  dotHoverScale: 2.6,
  // City markers
  cities: [],                 // ["London", { name, lat, lon, color? }, …]
  markers: [],                // coordinate pins: [{ name, lat, lon }, ...] — merged with cities
  focus: null,                // { lat, lon } the globe starts facing (rotate-speed 0 holds it)
  // Graticule — the meridian/parallel grid (globe mode). The equator is
  // drawn separately so it can carry its own weight: it is the line a
  // reader orients against.
  // How land is drawn. A space-separated token list, so combinations read
  // the way you would say them out loud. Works identically on both renderers:
  //   "dots"           the dot field mappo is named for (default)
  //   "solid"          filled landmass
  //   "outline"        coastline only
  //   "solid outline"  filled, with the coast drawn on top
  land: "dots",
  landColor: null,            // fill; defaults to dotColor
  landStroke: null,           // coastline; defaults to landColor, then dotColor
  landStrokeWidth: 1,
  // Where the coastline comes from: "grid" (traced from the bitmask — blocky,
  // follows cols, free) or "vector" (real Natural Earth outlines — smooth at
  // any size, ~13 KB).
  landSource: "grid",
  borders: false,             // country borders (vector data; any land style)
  bordersColor: null,         // defaults to the coastline colour
  bordersWidth: 0.5,
  bordersOpacity: 0.55,
  roll: 0,                    // globe LEAN, in the plane of the screen (deg)
  graticule: false,
  meridians: 12,              // evenly spaced longitudes
  parallels: 11,              // evenly spaced latitudes; the equator is extra
  graticuleColor: null,       // defaults to dotColor
  equatorColor: null,         // defaults to graticuleColor
  graticuleOpacity: 0.28,
  // Only a touch above the other lines. The equator earns its own colour
  // and weight option so it CAN be emphasised, but emphasising it by default
  // reads as a bug — one parallel inexplicably darker than its neighbours.
  equatorOpacity: 0.36,
  // Position host DOM carrying data-lat/data-lon over the map (globe mode).
  overlays: true,
  // Cap the canvas backing store. 3× devices buy no visible detail on a
  // dot field and pay full fill-rate for it.
  maxDpr: 2,
  highlightPolygon: null,     // rings of [lat, lon] — dots inside draw in highlightColor (globe mode)
  highlightColor: "#8fb0d8",
  markerShape: "circle",
  markerColor: "#2262fe",
  markerScale: 1.5,           // relative to a dot
  markerPulse: false,         // radar ping (expanding fading ring) — opt-in; mappo ships static by default
  markerHoverScale: 1.8,
  // Plane transform (degrees; the classic hero skew)
  tilt: 0,
  rotate: 0,
  perspective: 1000,
  // Animation animation over the whole matrix. Three plain-language knobs:
  animation: "none",            // "none" | "wave" | "noise" | "ripple" | "sweep" | "sparkle"
  animationPeriod: 6,           // seconds per full cycle (bigger = slower)
  animationHeight: 0.8,         // crest height, in CELLS (1 = one grid cell)
  animationWidth: 0.13,         // crest window as a fraction of the cycle (smaller = thinner front)
  // Interaction
  cursor: "default",
  markerCursor: "pointer",
  interactive: true,
  // Callbacks (each also fires as a bubbling CustomEvent "mappo:*")
  onDotClick: null,           // ({ lat, lon, col, row, element })
  onDotEnter: null,
  onCityClick: null,          // ({ name, lat, lon, element })
  onCityEnter: null
};

// Which update path each option needs. Callback keys appear in none of
// these on purpose: they're read at dispatch time, changing them costs
// nothing. Anything unlisted defaults to the safe full rebuild.
const STYLE_KEYS = new Set([
  "dotColor", "dotHoverColor", "dotHoverScale", "markerColor",
  "markerHoverScale", "tilt", "rotate", "perspective",
  "animation", "animationPeriod", "animationHeight", "animationWidth", "cursor", "markerCursor",
  // Backdrop knobs are pure stylesheet in flat mode: the bg rect and the
  // pattern-filled ocean rect always exist; only their fills change.
  "background", "globeRing"
]);
const DEF_KEYS = new Set(["dotShape", "dotSize", "markerShape", "markerScale", "oceanColor"]);
const MARKER_KEYS = new Set(["cities", "markerPulse", "interactive"]);
const CALLBACK_KEYS = new Set(["onDotClick", "onDotEnter", "onCityClick", "onCityEnter"]);

const SVG_NS = "http://www.w3.org/2000/svg";
const CELL = 10;        // internal SVG units per grid cell — never exposed

// Every instance scopes its own stylesheet to itself with this.
let instanceSeq = 0;
const MAX_COLS = 260;   // above this, SVG node count degrades interaction
const REBUILD_MS = 150; // min spacing between geometry rebuilds
// Animation noise field frequencies. PHASE picks when a dot moves, AMP how
// far — two octaves at different scales is what makes the surface read as
// organic material instead of a screensaver. 0.22 ≈ patches a few dots
// wide (the 0.09 v1 field produced continent-sized blobs — "too big").
const NOISE_PHASE_SCALE = 0.22;
const NOISE_AMP_SCALE = 0.31;

// Deep instrumentation, two layers:
// - performance.mark/measure spans ship ALWAYS (they cost ~nothing and make
//   any DevTools Performance trace self-documenting: look for "wm:*" blocks
//   in the flame chart).
// - console output is opt-in via `Mappo.debug = true` (the perf harness
//   turns it on) so production consumers get a silent component.
function span(name, fn) {
  const m0 = `${name}:start`;
  performance.mark(m0);
  const out = fn();
  performance.measure(name, m0);
  const entries = performance.getEntriesByName(name);
  const ms = entries[entries.length - 1]?.duration ?? 0;
  performance.clearMarks(m0);
  return [out, ms];
}
function dbg(...args) {
  if (Mappo.debug) console.debug("[mappo]", ...args);
}

export class Mappo {
  // Opt-in deep console output ("[mappo] …"). The perf harness sets this.
  static debug = false;
  // @param container [HTMLElement] emptied and rendered into; sizing is the
  //   consumer's (the svg scales to the container via viewBox).
  // @param options   [Object] see DEFAULTS.
  constructor(container, options = {}) {
    this.container = container;
    this.options = { ...DEFAULTS, ...options };
    this._dotsCache = new Map(); // "cols|latMin|latMax" → dots markup string
    this.render();
  }

  // Differential update — see the header. Public contract: call with any
  // subset of options, as often as you like; the component picks the
  // cheapest sufficient refresh and never lets bursts stack up.
  update(options = {}) {
    const changed = Object.keys(options).filter((k) => !sameOption(options[k], this.options[k]));
    Object.assign(this.options, options);
    if (changed.length === 0) return;

    if (changed.every((k) => CALLBACK_KEYS.has(k))) {
      dbg("update: callbacks only", changed, "→ no work");
      return; // read at dispatch time
    }

    // Globe mode sidesteps the SVG patch tiers entirely: the canvas redraws
    // every frame anyway, so any change is a cheap buffer/style refresh —
    // except a mode switch, which swaps renderers via the geometry path.
    if (changed.includes("mode")) {
      dbg("update: mode →", this.options.mode, "→ renderer swap");
      this.#scheduleRebuild();
      return;
    }
    if (this.options.mode === "globe") {
      if (this._globe) { this._globe.update(); dbg("update:", changed, "→ globe refresh"); }
      else this.#scheduleRebuild();
      return;
    }

    const styleOnly = changed.every((k) =>
      STYLE_KEYS.has(k) || DEF_KEYS.has(k) || MARKER_KEYS.has(k) || CALLBACK_KEYS.has(k));

    if (!styleOnly) {
      dbg("update:", changed, "→ GEOMETRY rebuild (debounced)");
      this.#scheduleRebuild();
      return;
    }
    const patches = [];
    if (changed.some((k) => DEF_KEYS.has(k))) {
      const [, defsMs] = span("wm:patch-defs", () => this.#patchDefs());
      patches.push(`defs ${defsMs.toFixed(1)}ms`);
    }
    if (changed.some((k) => MARKER_KEYS.has(k))) {
      const [, markersMs] = span("wm:patch-markers", () => this.#patchMarkers());
      patches.push(`markers ${markersMs.toFixed(1)}ms`);
    }
    const [, styleMs] = span("wm:patch-style", () => this.#patchStyle());
    patches.push(`style ${styleMs.toFixed(1)}ms`);
    dbg("update:", changed, "→", patches.join(" · "));
  }

  destroy() {
    clearTimeout(this._rebuildTimer);
    this._globe?.destroy();
    this._globe = null;
    this.container.replaceChildren();
  }

  // -- the full build (geometry path only) -------------------------------------

  // Leading + trailing debounce: an isolated change renders immediately; a
  // drag renders at most every REBUILD_MS with a guaranteed final render at
  // the resting value. This is the backpressure valve — without it, drag
  // input outruns render capacity and the tab drowns.
// Position adopted overlay children against the flat projection.
//
// Percentages, not pixels: the SVG scales with its container, so a percent
// stays correct through every resize without mappo having to watch for one.
// Depth is published as 1 — a flat map has no limb — so a stylesheet
// written against --mappo-depth for the globe works here unchanged.
_placeOverlays() {
  if (!this._overlayEls?.length) return;
  const latRange = this.options.latRange;
  for (const el of this._overlayEls) {
    const lat = Number(el.dataset.lat);
    const lon = Number(el.dataset.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    const p = projectNormalized(lat, lon, { latRange });
    el.style.left = `${(p.x * 100).toFixed(3)}%`;
    el.style.top = `${(p.y * 100).toFixed(3)}%`;
    el.style.setProperty("--mappo-depth", "1");
  }
}

  #scheduleRebuild() {
    // ADAPTIVE spacing (perf-harness lesson): a fixed 150ms floor against
    // 70-146ms renders is a ~50% main-thread duty cycle — the storm scenario
    // measured 49% blocked. Spacing self-tunes to ~8× the last measured
    // render cost (capped at 1.2s), so heavy resolutions rebuild ~1×/s
    // during a drag while cheap ones stay at the 150ms floor. Blocked time
    // lands near 12% on any machine, fast or slow.
    const spacing = Math.min(1200, Math.max(REBUILD_MS, (this._lastRenderMs ?? 0) * 8));
    const since = performance.now() - (this._lastRebuild ?? -Infinity);
    const wait = Math.max(0, spacing - since);
    dbg(`rebuild scheduled: ${wait === 0 ? "immediate (leading)" : `in ${wait.toFixed(0)}ms (trailing)`}`);
    clearTimeout(this._rebuildTimer);
    this._rebuildTimer = setTimeout(() => {
      if (this.container.isConnected) this.render();
    }, wait);
  }

  render() {
    this._lastRebuild = performance.now();
    const o = this.options;

    if (o.mode === "globe") {
      // Leaving the SVG scene: the canvas replaces the container's children,
      // so the persistent svg/style handles must not survive to be patched
      // while detached. Rebuilt from scratch on return to flat.
      if (this.svg) { this.svg = null; this.styleEl = null; }
      if (this._globe) this._globe.update();
      else this._globe = new GlobeRenderer(this.container, this.options);
      return;
    }
    if (this._globe) { this._globe.destroy(); this._globe = null; }

    const colsWanted = o.cols ?? 120; // auto default for the flat map
    const cols = Math.min(colsWanted, MAX_COLS);
    if (colsWanted > MAX_COLS) console.warn(`[mappo] cols capped at ${MAX_COLS} (asked for ${colsWanted}) — beyond that SVG interaction degrades (mode="globe" already renders on canvas; a flat canvas renderer is on the roadmap)`);
    const rows = Math.round((cols / 360) * (o.latRange[1] - o.latRange[0]));
    this.grid = { cols, rows, latRange: o.latRange };

    // PERSISTENT scene (heap-growth lesson): svg, tilt wrapper, style
    // element and listeners are created ONCE and reused forever — a rebuild
    // swaps viewBox + innerHTML in place. v2 recreated all three per rebuild
    // and re-bound listeners each time; across a slider storm that churned
    // tens of MB of discarded containers on top of the node garbage.
    const renderT0 = performance.now();
    if (!this.svg) {
      this.svg = document.createElementNS(SVG_NS, "svg");
      this.svg.setAttribute("class", "mappo-svg");
      this.svg.setAttribute("role", "img");
      this._tiltWrap = document.createElement("div");
      this._tiltWrap.className = "mappo-tilt";
      this._tiltWrap.appendChild(this.svg);
this.styleEl = document.createElement("style");
// Same contract as the globe: host DOM carrying data-lat/data-lon is
// adopted and positioned. On a flat map the position is static, so it
// is written once per build rather than per frame — but the markup,
// the attributes and the CSS hooks are identical, which is the point
// of having one overlay API rather than two.
this._overlayEls = this.options.overlays === false ? []
  : Array.from(this.container.querySelectorAll("[data-lat][data-lon]"));
if (this._overlayEls.length) {
  this._overlayLayer = document.createElement("div");
  this._overlayLayer.className = "mappo-overlay";
  Object.assign(this._overlayLayer.style, {
    position: "absolute", inset: "0", pointerEvents: "none"
  });
  for (const el of this._overlayEls) {
    Object.assign(el.style, { position: "absolute" });
    this._overlayLayer.appendChild(el);
  }
}
this.container.replaceChildren(this.styleEl, this._tiltWrap);
if (this._overlayLayer) {
  if (getComputedStyle(this.container).position === "static") {
    this.container.style.position = "relative";
  }
  this.container.appendChild(this._overlayLayer);
}
      this.#bindEvents(this.svg); // once — handlers guard on options.interactive
    }
    const svg = this.svg;
    svg.setAttribute("viewBox", `0 0 ${cols * CELL} ${rows * CELL}`);
    svg.setAttribute("aria-label", this.#ariaLabel());
    // One parse for the whole scene — the fast path for full builds.
    const [markup, buildMs] = span("wm:build-markup", () =>
      this.#defsMarkup(o) + this.#backdropMarkup(cols, rows) + (parseLandStyle(o.land).dots ? this.#dotsMarkup(this.grid) : this.#landMarkup(this.grid, o)) + this.#markersMarkup(this.grid, o));
    const [, parseMs] = span("wm:parse-innerHTML", () => { svg.innerHTML = markup; });
    this.#applyStyle(this.#css(o));
    // Calibration (perf-harness lesson #2): the JS-side cost is only ~25%
    // of a rebuild — the style recalc, layout and paint land AFTER this
    // function returns. Double-rAF closes the window after the browser has
    // actually produced the frame, so the adaptive spacing sees the TRUE
    // per-rebuild cost (~4× larger) and spaces drags honestly. The sync
    // value below is the headless/SSR fallback.
    this._lastRenderMs = performance.now() - renderT0;
    if (typeof requestAnimationFrame === "function") {
      requestAnimationFrame(() => requestAnimationFrame(() => {
        this._lastRenderMs = performance.now() - renderT0;
        dbg(`render calibrated: full frame cost ${this._lastRenderMs.toFixed(0)}ms → next spacing ${Math.min(1200, Math.max(REBUILD_MS, this._lastRenderMs * 8)).toFixed(0)}ms`);
      }));
    }
    dbg(`render: cols=${cols} rows=${rows} · build ${buildMs.toFixed(1)}ms · parse ${parseMs.toFixed(1)}ms · total ${this._lastRenderMs.toFixed(1)}ms · ${svg.querySelectorAll("*").length} nodes`);
    this._placeOverlays();
  }

  // -- cheap patches -----------------------------------------------------------

  #patchStyle() {
    this.#applyStyle(this.#css(this.options));
  }

  #patchDefs() {
    // Wholesale swap via the one true builder — a hand-maintained subset
    // here is how the ocean pattern got silently wiped by dot-shape patches.
    const defs = this.svg?.querySelector("defs");
    if (defs) defs.outerHTML = this.#defsMarkup(this.options);
  }

  #patchMarkers() {
    const group = this.svg?.querySelector(".mappo-markers");
    if (!group) return;
    group.remove();
    this.svg.insertAdjacentHTML("beforeend", this.#markersMarkup(this.grid, this.options));
    this.svg.setAttribute("aria-label", this.#ariaLabel());
  }

  // -- markup builders ---------------------------------------------------------

  #defsMarkup(o) {
    // The ocean is ONE pattern-filled rect, not thousands of nodes: the
    // pattern tiles the dot shape (at 0.62×) across every grid cell, and
    // the stylesheet colors it — so oceanColor stays a style-tier knob
    // even at max resolution.
    return `<defs>${
      this.#shapeMarkup("mappo-dot-shape", o.dotShape, o.dotSize)}${
      this.#shapeMarkup("mappo-marker-shape", o.markerShape, o.dotSize * o.markerScale)
    }<pattern id="mappo-ocean-pat" width="${CELL}" height="${CELL}" patternUnits="userSpaceOnUse">${this.#oceanDotMarkup(o)}</pattern></defs>`;
  }

  // A DIRECT shape with an inline fill — not <use>: CSS can't reliably
  // reach into a pattern's use-shadow tree across browsers (the original
  // implementation rendered nothing in some engines). The cost: oceanColor
  // is a defs-tier knob instead of style-tier. Still no geometry rebuild.
  #oceanDotMarkup(o) {
    if (!o.oceanColor || o.oceanColor === "none") return "";
    const r = (CELL * o.dotSize * 0.62) / 2;
    const c = CELL / 2;
    const fill = `fill="${escapeAttr(o.oceanColor)}"`;
    switch (o.dotShape) {
      case "square":
        return `<rect x="${c - r}" y="${c - r}" width="${r * 2}" height="${r * 2}" rx="${(r * 0.25).toFixed(2)}" ${fill}/>`;
      case "triangle":
        return `<path d="M${c} ${c - r} L${c + r} ${c + r} L${c - r} ${c + r} Z" ${fill}/>`;
      default: // circle + custom-path fallback
        return `<circle cx="${c}" cy="${c}" r="${r}" ${fill}/>`;
    }
  }

  // Backdrop layers, always present so background/oceanColor patch as pure
  // style. Both sit under the dots and ignore the pointer.
  #backdropMarkup(cols, rows) {
    const w = cols * CELL, h = rows * CELL;
    return `<rect class="mappo-bg" x="0" y="0" width="${w}" height="${h}"/>` +
           `<rect class="mappo-ocean" x="0" y="0" width="${w}" height="${h}" fill="url(#mappo-ocean-pat)"/>`;
  }

  // One reusable shape per role, centered on the local origin so inner-
  // element transforms scale in place.
  #shapeMarkup(id, shape, size) {
    const r = (CELL * size) / 2;
    switch (shape) {
      case "square": {
        return `<rect id="${id}" x="${-r}" y="${-r}" width="${r * 2}" height="${r * 2}" rx="${(r * 0.25).toFixed(2)}"/>`;
      }
      case "triangle":
        return `<path id="${id}" d="M0 ${-r} L${r} ${r} L${-r} ${r} Z"/>`;
      case "circle":
        return `<circle id="${id}" r="${r}"/>`;
      case "pin": {
        // Map-pin silhouette anchored at the TIP (origin = the place),
        // head floating above, punched hole — the canvas globe's twin.
        const pr = r * 1.24;
        const hy = (-pr * 1.9).toFixed(2);
        return `<path id="${id}" fill-rule="evenodd" d="M0 0 Q${(pr * 0.55).toFixed(2)} ${(Number(hy) + pr * 1.1).toFixed(2)} ${(pr * 0.966).toFixed(2)} ${(Number(hy) + pr * 0.259).toFixed(2)} A${pr.toFixed(2)} ${pr.toFixed(2)} 0 1 0 ${(-pr * 0.966).toFixed(2)} ${(Number(hy) + pr * 0.259).toFixed(2)} Q${(-pr * 0.55).toFixed(2)} ${(Number(hy) + pr * 1.1).toFixed(2)} 0 0 Z M0 ${hy} m${(-pr * 0.42).toFixed(2)} 0 a${(pr * 0.42).toFixed(2)} ${(pr * 0.42).toFixed(2)} 0 1 0 ${(pr * 0.84).toFixed(2)} 0 a${(pr * 0.42).toFixed(2)} ${(pr * 0.42).toFixed(2)} 0 1 0 ${(-pr * 0.84).toFixed(2)} 0"/>`;
      }
      default:
        // Custom SVG path, 24×24 box centered on origin (icon convention).
        return `<path id="${id}" d="${escapeAttr(shape)}" transform="scale(${((r * 2) / 24).toFixed(4)})"/>`;
    }
  }

  // Dot geometry depends ONLY on (cols, latRange) — colors, shapes and
  // animation all live elsewhere — so the markup string caches perfectly per
  // resolution. Both animation phases ship on every dot (~30 bytes each):
  // that's what makes animation a style-only knob.
  // lat/lon rings → SVG path data in this map's units. The same equirectangular
  // mapping the dot grid uses, so vector land lands exactly where grid land does.
  #vectorPath(rings, grid) {
    const [ latMin, latMax ] = grid.latRange;
    const w = grid.cols * CELL, h = grid.rows * CELL;
    const parts = [];
    for (const ring of rings) {
      let d = "";
      for (let i = 0; i < ring.length; i++) {
        const x = ((ring[i][1] + 180) / 360) * w;
        const y = ((latMax - ring[i][0]) / (latMax - latMin)) * h;
        d += `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`;
      }
      parts.push(`${d}Z`);
    }
    return parts.join("");
  }

  // Land as shape. `solid`, `outline` and `solid outline` are three renderings
  // of ONE geometry: the closed boundary contours from land.js. Because the
  // loops are closed and consistently wound, the same `d` both fills (holes
  // correct under fill-rule: nonzero) and strokes as a true coastline — no
  // internal cell edges, because a contour is only ever drawn where land meets
  // sea. Tracing per-cell rectangles instead would stroke a wireframe.
  #landMarkup(grid, o) {
    const style = parseLandStyle(o.land);
    const vector = landRings(o.landSource);
    // `borders` belongs in the key: the cached markup CONTAINS the borders
    // path, so leaving it out means turning borders off replays a cached scene
    // that still has them. (Caught by the demo toggles, not by a unit test —
    // cache keys only lie when you change the thing they forgot.)
    const key = `land|${o.landSource}|${o.borders ? "b" : ""}|${grid.cols}|${grid.latRange[0]}|${grid.latRange[1]}`;
    let geom = this._dotsCache.get(key);
    if (!geom) {
      const { cells, loops } = buildLand(grid);
      geom = {
        d: vector
          ? this.#vectorPath(vector, grid)
          : loops.map((loop) => `M${loop.map(([ x, y ]) => `${x * CELL} ${y * CELL}`).join("L")}Z`).join(""),
        borders: o.borders ? this.#vectorPath(borderRings(), grid) : "",
        cells
      };
      this._dotsCache.set(key, geom);
    }
    this._dotCount = geom.cells.length;

    const fill = style.fill ? (o.landColor ?? o.dotColor) : "none";
    const stroke = style.stroke ? (o.landStroke ?? o.landColor ?? o.dotColor) : "none";
    const width = o.landStrokeWidth ?? 1;
    // style= rather than fill=/stroke=: `fill="var(--x)"` is invalid, while the
    // style property resolves — so land follows the host's CSS variables with
    // no colour resolver on this side.
    const css = `fill:${escapeAttr(fill)};stroke:${escapeAttr(stroke)};` +
      `stroke-width:${width * (CELL / 10)};stroke-linejoin:round;fill-rule:nonzero`;
    const borders = geom.borders
      ? `<path class="mappo-borders" style="fill:none;stroke:${escapeAttr(o.bordersColor ?? stroke)};` +
        `stroke-width:${(o.bordersWidth ?? 0.5) * (CELL / 10)};stroke-linejoin:round;opacity:${o.bordersOpacity ?? 0.55}" d="${geom.borders}"/>`
      : "";
    return `<g class="mappo-land"><path class="mappo-land-path" style="${css}" d="${geom.d}"/>` +
      `${borders}${this.#landHighlightMarkup(grid, o)}</g>`;
  }

  // The highlight polygon in FLAT mode — the same ray-cast highlight.js already
  // did for the globe. A highlight is a FILL, so it paints the land cells inside
  // the region rather than tracing them: it reads as a lit area, and it reuses
  // the very cell list the contours were traced from.
  #landHighlightMarkup(grid, o) {
    if (!o.highlightPolygon?.length) return "";
    const normalized = normalizeRings(o.highlightPolygon);
    const { cells } = buildLand(grid);
    const parts = [];
    for (const [ col, row ] of cells) {
      const c = cellCenter(col, row, grid);
      if (!pointInRings(c.lat, c.lon, normalized)) continue;
      parts.push(`M${col * CELL} ${row * CELL}h${CELL}v${CELL}h-${CELL}Z`);
    }
    if (!parts.length) return "";
    return `<path class="mappo-land-highlight" style="fill:${escapeAttr(o.highlightColor)}" d="${parts.join("")}"/>`;
  }

  #dotsMarkup(grid) {
    const key = `${grid.cols}|${grid.latRange[0]}|${grid.latRange[1]}`;
    const cached = this._dotsCache.get(key);
    if (cached) { dbg(`dots cache HIT ${key}`); this._dotCount = cached.dots; return cached.markup; }
    dbg(`dots cache MISS ${key} — computing`);

    let dots = 0;
    const parts = [`<g class="mappo-dots">`];
    for (let row = 0; row < grid.rows; row++) {
      for (let col = 0; col < grid.cols; col++) {
        const c = cellCenter(col, row, grid);
        if (!isLand(c.lat, c.lon)) continue;
        dots++;

        // Every animation mode is a PHASE FIELD baked per dot; the stylesheet
        // picks which field feeds the animation delay. All pure functions of
        // (col,row) — that's what keeps this markup resolution-cacheable.
        const pw = ((col + row) / (grid.cols + grid.rows)).toFixed(3);          // diagonal front
        const pn = (((noise2(col * NOISE_PHASE_SCALE, row * NOISE_PHASE_SCALE) + 1) / 2)).toFixed(3); // organic patches
        const pr = (Math.hypot(col - grid.cols / 2, row - grid.rows / 2) /
          Math.hypot(grid.cols / 2, grid.rows / 2)).toFixed(3);                 // radial rings
        const ps = (col / grid.cols).toFixed(3);                                // west→east scanline
        const pk = (((noise2(col * 3.7 + 9, row * 3.7 + 9) + 1) / 2)).toFixed(3); // uncorrelated twinkle
        // Amplitude octave: 0.55–1.0 so every dot moves, none identically.
        const a = (0.55 + 0.45 * ((noise2(col * NOISE_AMP_SCALE + 47, row * NOISE_AMP_SCALE + 47) + 1) / 2)).toFixed(2);
        // Density classes for the animation LOAD GATE: at high resolutions the
        // stylesheet animates only .mappo-h (~1/2) or .mappo-t (~1/3) of dots —
        // SVG transforms are main-thread, and 8k continuous animators melt
        // frames; a baked checkerboard subset reads identically at density.
        const density = `${(col + row) % 2 === 0 ? " mappo-h" : ""}${(2 * col + 3 * row) % 3 === 0 ? " mappo-t" : ""}`;
        parts.push(
          `<g class="mappo-pos" transform="translate(${col * CELL + CELL / 2} ${row * CELL + CELL / 2})" data-col="${col}" data-row="${row}">` +
          `<use class="mappo-dot${density}" href="#mappo-dot-shape" style="--mappo-pw:${pw};--mappo-pn:${pn};--mappo-pr:${pr};--mappo-ps:${ps};--mappo-pk:${pk};--mappo-a:${a}"/></g>`
        );
      }
    }
    parts.push("</g>");
    const markup = parts.join("");
    this._dotCount = dots;

    this._dotsCache.set(key, { markup, dots });
    // Cap by BYTES, not entries: a resolution sweep can visit dozens of
    // grids and high-res strings run ~1MB each — an entry-count cap
    // measured as tens of MB of retained heap in the perf harness.
    this._cacheBytes = (this._cacheBytes ?? 0) + markup.length;
    while (this._cacheBytes > 4_000_000 && this._dotsCache.size > 1) {
      const oldest = this._dotsCache.keys().next().value;
      this._cacheBytes -= this._dotsCache.get(oldest).markup.length;
      this._dotsCache.delete(oldest);
    }
    return markup;
  }

  #markersMarkup(grid, o) {
    const parts = [`<g class="mappo-markers">`];
    for (const entry of [ ...o.cities, ...(o.markers || []) ]) {
      const city = resolveCity(entry);
      if (!city) {
        console.warn(`[mappo] unknown city: ${JSON.stringify(entry)} — not in the registry; pass { name, lat, lon } instead`);
        continue;
      }
      const { col, row } = snapToLand(city.lat, city.lon, grid);
      const fill = city.color ? ` style="fill:${escapeAttr(city.color)}"` : "";
      const focus = o.interactive ? ` tabindex="0" role="button" aria-label="${escapeAttr(city.name)}"` : "";
      // The ping ring renders BEHIND the core and animates independently —
      // the core barely breathes, the ring expands and fades. Scaling one
      // element for "pulse" read as throbbing, not pinging.
      parts.push(
        `<g class="mappo-pos" transform="translate(${col * CELL + CELL / 2} ${row * CELL + CELL / 2})" data-city="${escapeAttr(city.name)}" data-lat="${city.lat}" data-lon="${city.lon}"${focus}>` +
        (o.markerPulse ? `<use class="mappo-marker-ring" href="#mappo-marker-shape"${fill}/>` : "") +
        `<use class="mappo-marker" href="#mappo-marker-shape"${fill}/></g>`
      );
    }
    parts.push("</g>");
    return parts.join("");
  }

  // The component stylesheet — defaults, not law; outside CSS wins.
// Write the instance stylesheet, SCOPED TO THIS MAP.
//
// The rules are generated per instance but their selectors are generic
// (.mappo-dot, .mappo-marker …) and a <style> in the document applies to the whole
// document — so on a page with two maps the LAST one to render silently
// repainted every other one. Eight maps on the demo page all took the last
// map`s marker colour; only land escaped, because it carries an inline fill.
//
// Two things leak and both are handled: selectors get an attribute scope, and
// @keyframes NAMES get the same suffix, since two maps animating at different
// periods would otherwise define the same animation twice.
//
// Selectors are rewritten through the CSSOM rather than by regex on the text:
// the browser has already parsed the structure, so keyframe stops (`0%, 100%`)
// and at-rule preludes cannot be mistaken for selectors.
#applyStyle(css) {
  const uid = (this._uid ??= ++instanceSeq);
  // Node-safe, like the rest of this class's seams: the update-tier tests
    // drive the renderer with a stub container.
    this.container.setAttribute?.("data-mappo", uid);
  this.styleEl.textContent = css
    .replace(/@keyframes\s+(mappo-[\w-]+)/g, (_m, name) => `@keyframes ${name}-i${uid}`)
    .replace(/animation:\s*(mappo-[\w-]+)/g, (_m, name) => `animation: ${name}-i${uid}`);

  const sheet = this.styleEl.sheet;
  if (!sheet) return;                      // not yet in the document; next render scopes it
  const scope = `[data-mappo="${uid}"]`;
  const walk = (rules) => {
    for (const rule of rules) {
      if (rule.selectorText) {
        rule.selectorText = rule.selectorText.split(",")
          .map((sel) => `${scope} ${sel.trim()}`).join(", ");
      } else if (rule.cssRules && !rule.name) {   // @media etc; @keyframes has .name
        walk(rule.cssRules);
      }
    }
  };
  try { walk(sheet.cssRules); } catch { /* cross-origin or unparsed: leave global */ }
}

  #css(o) {
    return `
      .mappo-bg { fill: ${o.background === "none" ? "none" : o.background}; pointer-events: none; }
      .mappo-ocean { display: ${o.oceanColor === "none" ? "none" : "inline"}; pointer-events: none; }
      .mappo-tilt { perspective: ${o.perspective}px; }
      .mappo-tilt .mappo-svg {
        width: 100%; height: auto; display: block;
        transform: rotateX(${o.tilt}deg) rotateZ(${o.rotate}deg);
        transform-style: preserve-3d;
      }
      .mappo-dot {
        fill: ${o.dotColor};
        cursor: ${o.cursor};
        /* The hover wake: growing is INSTANT (transition:none below), the
           shrink-back runs slow and delayed — sweeping the cursor leaves a
           trail of settling dots. */
        transition: transform .3s ease .2s, fill .3s ease .2s;
      }
      ${o.interactive ? `
      .mappo-pos:hover > .mappo-dot {
        fill: ${o.dotHoverColor ?? hoverShade(o.dotColor)};
        transform: scale(${o.dotHoverScale});
        transition: none;
        animation: none; /* a running animation transform animation would win otherwise */
      }` : ""}
      .mappo-marker {
        fill: ${o.markerColor};
        cursor: ${o.markerCursor};
        ${o.markerPulse ? "animation: mappo-breathe 2.8s ease-in-out infinite;" : ""}
        transition: transform .2s ease;
      }
      .mappo-marker-ring {
        fill: ${o.markerColor};
        pointer-events: none;
        animation: mappo-ping 2.8s cubic-bezier(0, 0, 0.2, 1) infinite;
      }
      ${o.interactive ? `
      .mappo-pos:hover > .mappo-marker, .mappo-pos:focus-visible > .mappo-marker {
        animation: none;
        transform: scale(${o.markerHoverScale});
      }
      .mappo-pos:hover > .mappo-marker-ring, .mappo-pos:focus-visible > .mappo-marker-ring {
        animation: none;
        opacity: 0;
      }
      .mappo-markers .mappo-pos { outline: none; }` : ""}
      @keyframes mappo-ping {
        0%   { transform: scale(1);    opacity: .55; }
        70%  { transform: scale(2.75); opacity: 0; }
        100% { transform: scale(2.75); opacity: 0; }
      }
      @keyframes mappo-breathe {
        0%, 100% { transform: scale(1); }
        50%      { transform: scale(1.12); }
      }
      ${o.animation !== "none" ? (() => {
        // THE LOAD GATE: SVG transforms animate on the main thread, so the
        // number of continuous animators is the frame budget. Above ~4.5k
        // dots animate the baked half-density subset, above ~7k the third —
        // at those densities a subset moving reads identically, at half or
        // a third of the per-frame style cost. Decided per render from the
        // real dot count; logged so nobody wonders why some dots sit still.
        const dots = this._dotCount ?? 0;
        const sel = dots > 7000 ? ".mappo-t" : dots > 4500 ? ".mappo-h" : ".mappo-dot";
        if (sel !== ".mappo-dot") dbg(`animation load gate: ${dots} dots → animating ${sel} subset`);
        // Above the top gate, even the third-subset can drop frames on
        // mid-range hardware — SVG animation cost scales with animator
        // count and there is no compositor escape hatch. Say so out loud,
        // once: animation is DISRECOMMENDED at extreme resolutions.
        if (dots > 7000 && !this._animationWarned) {
          this._animationWarned = true;
          console.warn(`[mappo] animation="${o.animation}" with ${dots} dots: expect dropped frames on mid-range hardware. For animated maps keep cols <= 180 (~4.5k dots); reserve high resolutions for static maps. (Canvas renderer for extreme grids is on the roadmap.)`);
        }
        const dur = o.animationPeriod;
        const amp = o.animationHeight * CELL; // cells → SVG units
        // Window math: each mode's front is a multiple of animationWidth.
        // rise ≈ 38% into the window (fast up), settle at its end (slow down).
        const win = (mult) => {
          const w = Math.min(0.9, Math.max(0.02, o.animationWidth * mult));
          return { rise: (w * 38).toFixed(1), settle: (w * 100).toFixed(1) };
        };
        const wWave = win(1), wRipple = win(0.8), wSweep = win(0.5), wSparkle = win(0.55);
        const modes = {
          // A thin rolling crest along the diagonal — event, not texture.
          wave: `
      .mappo-dots ${sel} {
        animation: mappo-swell ${dur}s linear infinite;
        animation-delay: calc(var(--mappo-pw) * ${dur}s * -1);
      }
      @keyframes mappo-swell {
        0%   { transform: translateY(0) scale(1); }
        ${wWave.rise}%  { transform: translateY(calc(var(--mappo-a, 1) * -${amp}px)) scale(1.22); }
        ${wWave.settle}% { transform: translateY(0) scale(1); }
        100% { transform: translateY(0) scale(1); }
      }`,
          // Organic two-octave breathing — texture, not event.
          noise: `
      .mappo-dots ${sel} {
        animation: mappo-drift ${dur}s ease-in-out infinite;
        animation-delay: calc(var(--mappo-pn) * ${dur}s * -1);
      }
      @keyframes mappo-drift {
        0%, 100% { transform: translateY(0) scale(1); }
        50%      { transform: translateY(calc(var(--mappo-a, 1) * -${(amp * 0.75).toFixed(1)}px)) scale(1.1); }
      }`,
          // Concentric rings expanding from the map's center.
          ripple: `
      .mappo-dots ${sel} {
        animation: mappo-ripple ${dur}s linear infinite;
        animation-delay: calc(var(--mappo-pr) * ${dur}s * -1);
      }
      @keyframes mappo-ripple {
        0%   { transform: translateY(0) scale(1); }
        ${wRipple.rise}%  { transform: translateY(calc(var(--mappo-a, 1) * -${(amp * 0.8).toFixed(1)}px)) scale(1.18); }
        ${wRipple.settle}% { transform: translateY(0) scale(1); }
        100% { transform: translateY(0) scale(1); }
      }`,
          // A sonar scanline crossing west→east — the thinnest front.
          sweep: `
      .mappo-dots ${sel} {
        animation: mappo-sweep ${dur}s linear infinite;
        animation-delay: calc(var(--mappo-ps) * ${dur}s * -1);
      }
      @keyframes mappo-sweep {
        0%   { transform: translateY(0) scale(1); }
        ${wSweep.rise}% { transform: translateY(calc(var(--mappo-a, 1) * -${(amp * 0.7).toFixed(1)}px)) scale(1.28); }
        ${wSweep.settle}% { transform: translateY(0) scale(1); }
        100% { transform: translateY(0) scale(1); }
      }`,
          // Uncorrelated twinkle — quick scale pops scattered by high-freq noise.
          sparkle: `
      .mappo-dots ${sel} {
        animation: mappo-sparkle ${dur}s linear infinite;
        animation-delay: calc(var(--mappo-pk) * ${dur}s * -1);
      }
      @keyframes mappo-sparkle {
        0%   { transform: scale(1); }
        ${wSparkle.rise}% { transform: scale(calc(1 + var(--mappo-a, 1) * 0.45)); }
        ${wSparkle.settle}% { transform: scale(1); }
        100% { transform: scale(1); }
      }`
        };
        return modes[o.animation] ?? "";
      })() : ""}
      @media (prefers-reduced-motion: reduce) {
        .mappo-dot, .mappo-marker, .mappo-marker-ring { animation: none !important; transition: none !important; }
        .mappo-marker-ring { opacity: 0; }
      }
    `;
  }

  // -- events ------------------------------------------------------------------

  #bindEvents(svg) {
    const detailFor = (target) => {
      const pos = target.closest?.(".mappo-pos");
      if (!pos) return null;
      if (pos.dataset.city !== undefined) {
        return { kind: "city", detail: {
          name: pos.dataset.city,
          lat: Number(pos.dataset.lat),
          lon: Number(pos.dataset.lon),
          element: pos
        } };
      }
      const col = Number(pos.dataset.col), row = Number(pos.dataset.row);
      const c = cellCenter(col, row, this.grid);
      return { kind: "dot", detail: { lat: c.lat, lon: c.lon, col, row, element: pos } };
    };

    const dispatch = (kind, phase, detail) => {
      if (!this.options.interactive) return;
      const cb = this.options[`on${kind === "city" ? "City" : "Dot"}${phase}`];
      if (cb) cb(detail);
      this.container.dispatchEvent(new CustomEvent(
        `mappo:${kind}${phase.toLowerCase()}`,
        { detail, bubbles: true }
      ));
    };

    svg.addEventListener("click", (e) => {
      const hit = detailFor(e.target);
      if (hit) dispatch(hit.kind, "Click", hit.detail);
    });
    svg.addEventListener("mouseover", (e) => {
      // mouseover + a same-group guard ≈ mouseenter with one listener.
      const hit = detailFor(e.target);
      if (!hit) return;
      if (e.relatedTarget && hit.detail.element.contains(e.relatedTarget)) return;
      dispatch(hit.kind, "Enter", hit.detail);
    });
    svg.addEventListener("keydown", (e) => {
      if (e.key !== "Enter" && e.key !== " ") return;
      const hit = detailFor(e.target);
      if (hit?.kind === "city") { e.preventDefault(); dispatch("city", "Click", hit.detail); }
    });
  }

  #ariaLabel() {
    const names = this.options.cities.map((c) => resolveCity(c)?.name).filter(Boolean);
    return names.length
      ? `Dotted world map highlighting ${names.join(", ")}`
      : "Dotted world map";
  }
}

// Snap a lat/lon to the nearest LAND dot in the grid, searching outward a
// few rings — coastal cities often sit in a sea cell at coarse resolutions
// (harbors do that), and a marker floating just off the coast looks broken.
// Pure function (exported for tests and consumers doing their own math).
export function snapToLand(lat, lon, grid) {
  const { x, y } = project(lat, lon, grid);
  const col0 = Math.min(grid.cols - 1, Math.max(0, Math.floor(x)));
  const row0 = Math.min(grid.rows - 1, Math.max(0, Math.floor(y)));

  for (let radius = 0; radius <= 3; radius++) {
    let best = null;
    for (let dr = -radius; dr <= radius; dr++) {
      for (let dc = -radius; dc <= radius; dc++) {
        if (Math.max(Math.abs(dr), Math.abs(dc)) !== radius) continue; // ring only
        const col = col0 + dc, row = row0 + dr;
        if (col < 0 || col >= grid.cols || row < 0 || row >= grid.rows) continue;
        const c = cellCenter(col, row, grid);
        if (!isLand(c.lat, c.lon)) continue;
        const d = (col - x) ** 2 + (row - y) ** 2;
        if (!best || d < best.d) best = { col, row, d };
      }
    }
    if (best) return best;
  }
  // Deep-ocean coordinates render where they are — honest, and it makes
  // custom "cities" like ships or islands-below-resolution still work.
  return { col: col0, row: row0 };
}

// Option equality for the differential update: cities and latRange are the
// only structural values; everything else compares by identity.
function sameOption(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) return JSON.stringify(a) === JSON.stringify(b);
  return false;
}

function escapeAttr(value) {
  return String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

// ══════════ src/element.js ══════════
// <mappo-world> — the zero-JS way in. Every renderer option that makes
// sense as markup is an attribute; change an attribute, the map re-renders.
//
//   <mappo-world cities="London, Lagos, Singapore" tilt="40"
//                 dot-shape="circle" marker-color="#2262fe"></mappo-world>
//
// Callbacks aren't attributes (functions don't serialize) — listen for the
// bubbling CustomEvents instead: mappo:cityclick, :cityenter,
// :dotclick, :dotenter. For full control, use the Mappo class.


const ATTR_MAP = {
  // attribute      → [option, parser]
  "mode":             ["mode", String],
  "globe-ring":       ["globeRing", (v) => v !== "false"],
  "land":             ["land", String],
  "land-color":       ["landColor", String],
  "land-stroke":      ["landStroke", String],
  "land-stroke-width":["landStrokeWidth", Number],
  "land-source":      ["landSource", String],
  "borders":          ["borders", (v) => v !== "false"],
  "borders-color":    ["bordersColor", String],
  "borders-width":    ["bordersWidth", Number],
  "borders-opacity":  ["bordersOpacity", Number],
  "roll":             ["roll", Number],
  "graticule":        ["graticule", (v) => v !== "false"],
  "meridians":        ["meridians", Number],
  "parallels":        ["parallels", Number],
  "graticule-color":  ["graticuleColor", String],
  "equator-color":    ["equatorColor", String],
  "graticule-opacity":["graticuleOpacity", Number],
  "equator-opacity":  ["equatorOpacity", Number],
  "overlays":         ["overlays", (v) => v !== "false"],
  "max-dpr":          ["maxDpr", Number],
  "background":       ["background", String],
  "ocean-color":      ["oceanColor", String],
  "rotate-speed":     ["rotateSpeed", Number],
  "cols":             ["cols", Number],
  "lat-min":          ["latMin", Number],   // folded into latRange below
  "lat-max":          ["latMax", Number],
  "dot-shape":        ["dotShape", String],
  "dot-size":         ["dotSize", Number],
  "dot-color":        ["dotColor", String],
  "dot-hover-color":  ["dotHoverColor", String],
  "dot-hover-scale":  ["dotHoverScale", Number],
  "cities":           ["cities", (v) => v.split(",").map((s) => s.trim()).filter(Boolean)],
  // Coordinate markers, no gazetteer: "48.2,16.4;Vienna@48.2,16.4" —
  // semicolon-separated, optional Name@ prefix. Feeds the same pipeline
  // as cities (resolveCity already passes {lat, lon, name} through).
  "markers":          ["markers", (v) => v.split(";").map((tok) => {
                        const m = tok.trim().match(/^(?:(.*)@)?(-?[\d.]+)\s*,\s*(-?[\d.]+)$/);
                        return m ? { name: m[1] || "", lat: Number(m[2]), lon: Number(m[3]) } : null;
                      }).filter(Boolean)],
  // "lat,lon" the globe starts FACING (and the flat map centers its
  // marker composition around visually) — rotate-speed 0 holds it there.
  "focus":            ["focus", (v) => {
                        const m = v.trim().match(/^(-?[\d.]+)\s*,\s*(-?[\d.]+)$/);
                        return m ? { lat: Number(m[1]), lon: Number(m[2]) } : null;
                      }],
  // Region highlight (globe mode): JSON rings of [lat, lon] pairs —
  // either one ring or an array of rings. The CONSUMER supplies the
  // shape (Natural Earth etc.); mappo ships no boundary data.
  "highlight-polygon": ["highlightPolygon", (v) => {
                        try {
                          const parsed = JSON.parse(v);
                          if (!Array.isArray(parsed) || !parsed.length) return null;
                          return Array.isArray(parsed[0][0]) ? parsed : [ parsed ];
                        } catch { return null; }
                      }],
  "highlight-color":  ["highlightColor", String],
  "marker-shape":     ["markerShape", String],
  "marker-color":     ["markerColor", String],
  "marker-scale":     ["markerScale", Number],
  "marker-pulse":     ["markerPulse", (v) => v !== "false"],
  "tilt":             ["tilt", Number],
  "rotate":           ["rotate", Number],
  "perspective":      ["perspective", Number],
  "animation":          ["animation", String],
  "animation-period": ["animationPeriod", Number],
  "animation-height": ["animationHeight", Number],
  "animation-width": ["animationWidth", Number],
  "cursor":           ["cursor", String],
  "marker-cursor":    ["markerCursor", String],
  "interactive":      ["interactive", (v) => v !== "false"]
};

// Conditional class expression, not a declaration: `extends HTMLElement`
// evaluates at definition time, and this module must stay importable where
// no DOM exists (Node tests, SSR pipelines). There, the element export is
// null and register() no-ops — the data/geometry APIs still work.
export const MappoElement = typeof HTMLElement === "undefined" ? null :
class MappoElement extends HTMLElement {
  static observedAttributes = Object.keys(ATTR_MAP);

  connectedCallback() {
    // Light DOM on purpose: consumers restyle .mappo-dot/.mappo-marker with plain
    // CSS — a shadow root would wall that off for zero benefit here.
    this.map = new Mappo(this, this.#optionsFromAttributes());
  }

  disconnectedCallback() {
    this.map?.destroy();
    this.map = null;
  }

  attributeChangedCallback() {
    // Fires before connect for initial attributes; only re-render when live.
    this.map?.update(this.#optionsFromAttributes());
  }

  #optionsFromAttributes() {
    const options = {};
    for (const [attr, [key, parse]] of Object.entries(ATTR_MAP)) {
      const raw = this.getAttribute(attr);
      // An ABSENT attribute must mean "the default", not "whatever it was set
      // to last time". update() merges, so without this branch removing an
      // attribute never un-sets its option — `graticule`, `borders`,
      // `globe-ring` and every other boolean would latch on forever once
      // switched on. (Found by clicking the demo page toggles, which is
      // exactly the bug a unit test on a fresh instance cannot see.)
      if (raw !== null) options[key] = parse(raw);
      else if (key in DEFAULTS) options[key] = DEFAULTS[key];
    }
    if (options.latMin !== undefined || options.latMax !== undefined) {
      options.latRange = [options.latMin ?? -58, options.latMax ?? 84];
      delete options.latMin;
      delete options.latMax;
    }
    return options;
  }
};

export function register(tag = "mappo-world") {
  if (!MappoElement || customElements.get(tag)) return;
  hideOverlaysUntilDefined(tag);
  customElements.define(tag, MappoElement);
}

// Overlay children are ordinary markup, which means the browser lays them out
// the moment it parses them — before this module has loaded and long before
// the map knows where they belong. Without this they appear stacked in the
// corner of the element for a frame or two and then jump to their coordinates,
// which reads as broken. `:not(:defined)` holds them until the element upgrades;
// after that mappo owns their transform and the rule stops matching.
function hideOverlaysUntilDefined(tag) {
  if (typeof document === "undefined" || document.getElementById("mappo-upgrade-style")) return;
  const style = document.createElement("style");
  style.id = "mappo-upgrade-style";
  style.textContent = `${tag}:not(:defined) [data-lat][data-lon]{visibility:hidden}`;
  document.head?.prepend(style);
}
// ══════════ auto-register ══════════
if (typeof customElements !== "undefined") register();
